  ui_story_5020_50200202_10_dialog_content = "<anim type=Shake>อาาา...</anim>",
  ui_story_5020_50200202_11_dialog_content = "PlayerName? ทำอะไรอยู่?",
  ui_story_5020_50200202_12_dialog_content = "คุณพึมพำกับตัวเองแปลกๆ มาระยะหนึ่งแล้ว",
