  ui_story_5020_50200202_37_dialog_content = "<size=45>เจ้าผีพวกนี้มาทำอะไรที่นี่เนี่ย?!</size>",
  ui_story_5020_50200202_38_dialog_content = "เฮ้! PlayerName! ทำไมคุณกับคนอื่น ๆ ถึงยังไม่หนีไป?",
  ui_story_5020_50200202_39_dialog_content = "พวกเขากำลังพลิกแผงขายของทั้งหมด! ล่าถอย! ล่าถอย!",
