  ui_story_5020_50200202_45_dialog_content = "พวกเธออยากให้ร้านตัวเองดังกว่านี้ใช่มั้ย?",
  ui_story_5020_50200202_46_dialog_content = "<size=45>ใช่!</size>",
  ui_story_5020_50200202_47_dialog_content = "คุณอยากเป็นเจ้าของร้านอาหารที่ดีที่สุดใน Cloud Island ใช่ไหม?",
  ui_story_5020_50200202_48_dialog_content = "<size=45>ใช่!</size>",
  ui_story_5020_50200202_49_dialog_content = "ถ้าอย่างนั้น ใช้... อะแฮ่ม... ความร้อนแรงของคุณเพื่อนำคนเหล่านี้ไปยังที่ปลอดภัย",
  ui_story_5020_50200202_50_dialog_content = "<anim type=Shake><size=50>ได้สิ มาทางนี้เลย ทุกคน! ตามมาเร็วเข้า!!!</size></anim>",
  ui_story_5020_50200202_51_dialog_content = "โอย หูฉัน...",
  ui_story_5020_50200301_1_dialog_content = "ท่านคุโบะ มีพ่อค้าหลายคนรออยู่นอกปราสาทหลัก พวกเขาแสวงหาผู้ชมของคุณ",
  ui_story_5020_50200301_2_dialog_content = "ตอนนี้ตลอดเวลา? คืนนี้พวกเขาไม่ควรจะเร่ขายสินค้าตามท้องถนนหรือ?",
  ui_story_5020_50200301_3_dialog_content = "เอาเถอะ ให้พวกนั้นเข้ามา",
