  ui_story_5020_50200301_5_dialog_content = "ไม่ต้องมากพิธีหรอก บอกมาซิว่าเกิดอะไรขึ้น",
  ui_story_5020_50200301_6_dialog_content = "นายท่าน ท่านคงยังไม่ทราบเรื่อง! พวกผีบุกเข้ามาโจมตีซาคาอิแล้ว!",
  ui_story_5020_50200301_7_dialog_content = "ถูกตัอง! ถูกตัอง!",
  ui_story_5020_50200301_8_dialog_content = "แผงลอยของเราเป็นชิ้น ๆ ! เราทุกคนสูญเสียเงินจำนวนมากในคืนนี้...",
  ui_story_5020_50200301_9_dialog_content = "เทศกาล Kasuga จะไม่เหมือนเดิมในปีนี้...",
  ui_story_5020_50200301_10_dialog_content = "*กระแอม* นี่มันใช่เวลามาคร่ำครวญเรื่องเล็กน้อยพวกนี้ไหม? เงียบก่อนเถอะน่า!",
  ui_story_5020_50200301_11_dialog_content = "ต้องขออภัยด้วย ท่านคุโบ พวกเรารีบมาแจ้งเหตุโดยเร็วที่สุดแล้ว",
  ui_story_5020_50200301_12_dialog_content = "เป็นเรื่องจริงรึ?",
  ui_story_5020_50200301_13_dialog_content = "ยกโทษให้ฉัน Kubou-sama แต่ผู้พิทักษ์ตอนนี้—",
  ui_story_5020_50200301_14_dialog_content = "ส่งพวกเขาไปที่ Sakai เดี๋ยวนี้!",
  ui_story_5020_50200301_15_dialog_content = "ถ้าพวกเจ้ายังทำตัวเหลวไหลอีก ข้าจะตัดหัวเจ้าซะ!",
  ui_story_5020_50200301_16_dialog_content = "ขอรับ!",
  ui_story_5020_50200301_17_dialog_content = "ช่างเป็นความกรุณาอันล้นพ้น นายท่าน!",
  ui_story_5020_50200301_18_dialog_content = "ลูกน้องของข้าทำพลาด เรื่องนี้เป็นความผิดของข้าเอง ข้าควรกล่าวขอโทษพวกเจ้า",
  ui_story_5020_50200301_19_dialog_content = "เปล่าเลยนะ!",
  ui_story_5020_50200301_20_dialog_content = "ที่จริงแล้ว ตอนนี้ท่านรินเนะก็กำลังช่วยอพยพชาวเมืองไปยังที่ปลอดภัย",
  ui_story_5020_50200301_21_dialog_content = "หืม? รินเนะอยู่ในเมืองงั้นรึ?",
  ui_story_5020_50200301_22_dialog_content = "ใช่! Rinne-sama ต้องเตรียมพร้อมสำหรับเทศกาลกลางคืน เพื่อให้เธอตอบสนองต่อการโจมตีได้อย่างรวดเร็ว",
  ui_story_5020_50200301_23_dialog_content = "การปรากฏตัวของเธอที่กล้าหาญจับใจเราทุกคน!",
  ui_story_5020_50200301_24_dialog_content = "และนั่นทำให้เรารู้สึกว่าควรจะช่วยอะไรเธอบ้าง",
  ui_story_5020_50200301_25_dialog_content = "เมื่อได้เห็นเธอยุ่งกับการปกป้องเรา เราจึงคิดว่าเธอน่าจะไม่ว่างมาแจ้งข่าวให้ท่านทราบ ดังนั้น เราจึงเดินทางมาบอกท่านเอง โปรดให้อภัยพวกเราด้วย ท่านคุโบ!",
  ui_story_5020_50200301_26_dialog_content = "จะขอโทษขอโพยไปทำไม พวกเจ้าทุกคนทำสิ่งที่ถูกต้องแล้ว",
  ui_story_5020_50200301_27_dialog_content = "ฉันเชื่อว่ากองกำลังกบฏต้องโทษว่าเป็นผู้นำผีเข้ามาในเมือง พวกเขาต้องพยายามใช้ความโกลาหลเพื่อสานต่อแผนการของพวกเขา แม้จะต้องแลกกับความปลอดภัยของผู้คนก็ตาม",
  ui_story_5020_50200301_28_dialog_content = "แต่ไม่ต้องกลัว ทหารคุ้มกันกำลังออกเดินทางแล้ว รับรองว่าพวกเจ้าจะต้องปลอดภัย",
  ui_story_5020_50200301_29_dialog_content = "Cloud Island มีความสุขที่มีคุณ Kubou-sama!",
  ui_story_5020_50200301_30_dialog_content = "เราจะลากันเดี๋ยวนี้",
  ui_story_5020_50200301_31_dialog_content = "ผู้คนใน Cloud Island ไม่เข้าใจความหมายของสันติภาพ... สิ่งที่พวกเขารู้คือการเรียกร้องไม่รู้จบ",
  ui_story_5020_50200301_32_dialog_content = "เพื่อให้ความปรารถนาของเธอเป็นจริง ต้องเสียสละบางอย่าง",
  ui_story_5020_50200301_33_dialog_content = "แต่ที่น่าแปลกใจกว่านั้นคือ <color=#FFB400>กำมือ</color> ยังไม่ได้ดำเนินการ",
  ui_story_5020_50200301_34_dialog_content = "เจอตัวนากิหรือยัง?",
  ui_story_5020_50200301_35_dialog_content = "ยังเลยครับ",
  ui_story_5020_50200301_36_dialog_content = "<size=45>เจ้าพวกโง่ไร้ประโยชน์!</size>",
  ui_story_5020_50200301_37_dialog_content = "ฉันขอโทษคุโบ-ซามะ",
  ui_story_5020_50200301_38_dialog_content = "นำกองทัพผีสู่เมืองซาไก ที่ควรดึงพวกเขาออกมา",
  ui_story_5020_50200301_39_dialog_content = "เราจะต้องจบเรื่องทุกอย่างในวันนี้ให้ได้",
  ui_story_5020_50200301_40_dialog_content = "เทศกาลคาสึกะจะต้องดำเนินไปอย่างราบรื่น",
  ui_story_5020_50200301_41_dialog_content = "รับทราบ",
  ui_story_5020_50200301_42_dialog_content = "บางครั้งรินเนะก็เหมือนเจ้าเหลือเกิน",
  ui_story_5020_50200301_43_dialog_content = "ถ้าเพียงแต่คุณยังอยู่ที่นี่... ฉันแน่ใจว่าคุณจะต้องชอบเธอมากทีเดียว",
  ui_story_5020_50200301_44_dialog_content = "ตั้งแต่วันที่เธอจากไป ฉันตั้งความหวังทั้งหมดไว้ที่การเลี้ยงดูนักบวชหญิงคนใหม่",
  ui_story_5020_50200301_45_dialog_content = "แต่ก็เห็นได้ชัดว่าความพยายามทุกอย่างของข้านั้นไร้ความหมาย",
  ui_story_5020_50200301_46_dialog_content = "คุณคือคนพิเศษในที่สุด",
  ui_story_5020_50200301_47_dialog_content = "แต่จงวางใจได้ ข้าจะทำตามสัญญาที่ให้ไว้กับเจ้า",
  ui_story_5020_50200301_48_dialog_content = "เพราะนี่เป็นความปรารถนาของเจ้า... และเป็นสิ่งที่ข้าปรารถนาเช่นกัน",
  ui_story_5020_50200301_49_dialog_content = "<anim type=Shake><size=45>กรร!</size></anim>",
  ui_story_5020_50200301_50_dialog_content = "มีมากเกินไป!",
  ui_story_5020_50200301_51_dialog_content = "นี่โชกุนฟูจิคุโมะตั้งใจจะปล่อยให้ชาวเมืองตายโดยไม่ทำอะไรเลยเหรอ?",
  ui_story_5020_50200301_52_dialog_content = "น้ำวนเชี่ยวกราก—",
  ui_story_5020_50200301_53_dialog_content = "ผีพวกนี้แข็งแกร่งขึ้นเรื่อย ๆ เลย...",
  ui_story_5020_50200301_54_dialog_content = "ต้องโฟกัส... สิ่งที่เราให้ความสำคัญสูงสุดคือการพาพลเรือนออกไปจากที่นี่",
  ui_story_5020_50200301_55_dialog_content = "รินเนะ... ไวซ์... อดทนอีกนิดนึงนะ!",
  ui_story_5020_50200302_1_dialog_content = "หวังว่าทางฝั่งของโมโมะกับอันสึจะปลอดภัยดีนะ...",
  ui_story_5020_50200302_2_dialog_content = "<size=33>คุณ PlayerName!</size>",
  ui_story_5020_50200302_3_dialog_content = "เมื่อกี้มีคนเรียกชื่อฉันเหรอ?",
  ui_story_5020_50200302_4_dialog_content = "ฮะ? ฉันไม่ได้ยินอะไรเลย",
  ui_story_5020_50200302_5_dialog_content = "คุณ PlayerName!!",
  ui_story_5020_50200302_6_dialog_content = "เดี๋ยวนะ ฉันว่าฉันได้ยินแล้ว",
  ui_story_5020_50200302_7_dialog_content = "ดูเหมือนว่าจะมีคนตรงมาหาเราล่ะ!",
  ui_story_5020_50200302_8_dialog_content = "<size=50>คุณ PlayerName!!!</size>",
  ui_story_5020_50200302_9_option_content = "โมโมะ?!",
  ui_story_5020_50200302_10_dialog_content = "คุณไม่ควรจะอพยพพลเรือนไปกับ Anzu ไม่ใช่เหรอ?",
  ui_story_5020_50200302_11_option_content = "อันสึ?!",
  ui_story_5020_50200302_12_dialog_content = "คุณไม่ควรจะอพยพพลเรือนกับ Momo ไม่ใช่เหรอ?",
  ui_story_5020_50200302_13_dialog_content = "เลขที่, PlayerName! ฉันโมโม่!",
  ui_story_5020_50200302_14_dialog_content = "โอ้! S-ขอโทษด้วย... แค่คุณสองคนดูคล้ายกันจริงๆ",
  ui_story_5020_50200302_15_dialog_content = "คุณมาทำอะไรที่นี่? Anzu และพลเรือนอยู่ที่ไหน",
  ui_story_5020_50200302_16_dialog_content = "ฉันอยู่ที่นี่!",
  ui_story_5020_50200302_17_dialog_content = "ทำไมพวกเธอสองคนพาชาวเมืองกลับมาล่ะ?!",
  ui_story_5020_50200302_18_dialog_content = "เรายังไม่ได้ออกไปไหนเลย! ระหว่างที่พวกคุณคุ้มกันแนวหลัง ก็มีผีมากมายโผล่มาขวางทางข้างหน้า!",
  ui_story_5020_50200302_19_dialog_content = "เราถูกล้อมไว้หมดแล้ว!",
  ui_story_5020_50200302_20_dialog_content = "\"ในช่วงเวลาที่ยากลำบากนี้ เราทุกคนต้องตัดเส้นทางสู่ชัยชนะของตัวเอง!\"",
  ui_story_5020_50200302_21_dialog_content = "ทำไมฟังดูคุ้น ๆ จัง?",
  ui_story_5020_50200302_22_dialog_content = "งั้นเหรอ?",
  ui_story_5020_50200302_23_dialog_content = "ฉันพลิกอ่านคู่มือท่องเที่ยวเกาะเมฆของเหยาเมื่อนานมาแล้ว",
  ui_story_5020_50200302_24_dialog_content = "นี่เป็นหนึ่งในสโลแกนที่ใช้ในส่วนแฟชั่นของโบรชัวร์",
  ui_story_5020_50200302_25_dialog_content = "พูดตามตรงนะ รินเนะ... ฉันไม่คิดว่ามันจะเป็นสไตล์ของเธอจริงๆ...",
  ui_story_5020_50200302_26_dialog_content = "เหรอ? ฉันว่ามันก็เท่ดีออก!",
  ui_story_5020_50200302_27_dialog_content = "ด้วยเหตุผลแปลกๆ บางอย่าง...",
  ui_story_5020_50200302_28_dialog_content = "ฉันนึกภาพชินซาที่แต่งตัวเป็นซามูไรเกาะเมฆเกเรออกจากหัวไม่ได้เลย",
  ui_story_5020_50200302_29_dialog_content = "พอพูดแบบนั้น... ฉันก็นึกภาพตามขึ้นมาเลย",
  ui_story_5020_50200302_30_dialog_content = "เอาล่ะ! ได้เวลาตัดหนทางสู่ชัยชนะแล้ว!",
  ui_story_5020_50200302_31_dialog_content = "ทหาร กำจัดมันให้หมด!",
  ui_story_5020_50200302_32_dialog_content = "บุก!!!",
  ui_story_5020_50200302_33_dialog_content = "อ-อะไรเนี่ย...?!",
  ui_story_5020_50200302_34_dialog_content = "โชกุนส่งทหารมาแค่นี้เองเหรอ?",
  ui_story_5020_50200302_35_dialog_content = "ดูจากการแต่งตัวแล้ว ฉันเดาว่าพวกเขาเป็นคนธรรมดา",
  ui_story_5020_50200302_36_dialog_content = "พวกเขาเป็นกบฏ",
  ui_story_5020_50200302_37_dialog_content = "นั่นคือ <color=#FFB400>กำมือ</color> ถึงคุณ ขอบคุณมาก!",
  ui_story_5020_50200302_38_dialog_content = "ตอนนี้คุณเป็นใครมาก?",
  ui_story_5020_50200302_39_dialog_content = "คือ...",
  ui_story_5020_50200302_40_dialog_content = "มิโกะกับคนต่างแดนงั้นเหรอ?",
  ui_story_5020_50200302_41_dialog_content = "คว้า 'em!",
  ui_story_5020_50200401_1_dialog_content = "<anim type=Shake>ฮัดเช่ย!</anim>",
  ui_story_5020_50200401_2_dialog_content = "เฮ่อ... ต้องมีคนนินทาฉันอยู่แน่เลย",
  ui_story_5020_50200401_3_dialog_content = "ฉันสควอตจนเมื่อยขาไปหมดแล้ว... แต่ดูเหมือนข้างนอกจะปลอดภัยแล้วนะ",
  ui_story_5020_50200401_4_dialog_content = "อ่า ดีขึ้นมาก! การยืดเส้นยืดสายเล็กน้อยช่วยได้เสมอ!",
  ui_story_5020_50200401_5_dialog_content = "<anim type=Shake>กรร...</anim>",
  ui_story_5020_50200401_6_dialog_content = "ผีพวกนี้เข้ามาในปราสาทหลักได้ไงกัน?",
  ui_story_5020_50200401_7_dialog_content = "<size=45>ฮ่าห์!</size>",
  ui_story_5020_50200401_8_dialog_content = "อะไรของตาแก่นั่นนะ? แม้แต่ปราสาทหลักของตัวเองก็รักษาไว้ไม่อยู่เรอะ?",
  ui_story_5020_50200401_9_dialog_content = "และตอนนี้ทรงผมของฉันพังหมดแล้ว! คำสาป... รู้ไหมกว่าจะมัดแบบนี้ใช้เวลานานเท่าไหร่?!",
  ui_story_5020_50200401_10_dialog_content = "ว่าแต่... ฉันอยู่ตรงไหนแล้วเนี่ย?",
  ui_story_5020_50200401_11_dialog_content = "ปราสาทมันใหญ่เหลือเกิน... แถมทุกชั้นก็หน้าตาเหมือน ๆ กันอีก",
  ui_story_5020_50200401_12_dialog_content = "ฉันเคยมาโถงทางเดินตรงนี้รึยังนะ",
  ui_story_5020_50200401_13_dialog_content = "เอ่อ ไม่ดีเลย... ฉันต้องทิ้งเครื่องหมายไว้หรืออะไรซักอย่าง",
  ui_story_5020_50200401_14_dialog_content = "ว๊าย นี่มันผีร้ายชัดๆ... นายคงกินอะไรมาเยอะแล้วใช่ไหม?",
  ui_story_5020_50200401_15_dialog_content = "เอาล่ะ ถ้าฉันตั้งมันไว้แบบนี้... ทำแขนแบบนี้... ให้มันชี้ไปทางนั้น...",
  ui_story_5020_50200401_16_dialog_content = "โวล่า! ตอนนี้ฉันรู้แล้วว่าฉันจะไปทางไหน!",
  ui_story_5020_50200401_17_dialog_content = "แต่ว่า... แหวะ เหม็นชะมัด",
  ui_story_5020_50200401_18_dialog_content = "... ทางออกอยู่ไหน ?! ผีไม่ขอแตะอีก!!",
  ui_story_5020_50200401_19_dialog_content = "อ๊าก นี่มันแย่มาก! ฉันสาบาน ฉันจะอาบน้ำอย่างน้อยสิบครั้งทันทีที่ฉันกลับมา!",
  ui_story_5020_50200401_20_dialog_content = "<color=#e8d9bb>ปึง...!</color>",
  ui_story_5020_50200401_21_dialog_content = "<color=#e8d9bb>ปึง ปึง...!</color>",
  ui_story_5020_50200401_22_dialog_content = "อึ๊ย... นั่นเสียงกลองไทโกะที่รินเนะพูดถึงก่อนหน้านี้เหรอ?",
  ui_story_5020_50200401_23_dialog_content = "ฉันหลงอยู่ในนี้นานแค่ไหนแล้วเนี่ย?!",
  ui_story_5020_50200401_24_dialog_content = "Grr... ไปด้วยกัน เย้า! เอาล่ะ สมอง เราต้องคิดอะไรบางอย่างให้ออก!",
  ui_story_5020_50200401_25_dialog_content = "PlayerName บอกว่าให้พึ่งลางสังหรณ์",
  ui_story_5020_50200401_26_dialog_content = "แล้วลางสังหรณ์ของฉันก็บอกว่าให้ไปทางนี้...",
  ui_story_5020_50200401_27_dialog_content = "จากนั้นมันก็ให้ฉันเลี้ยวซ้าย...",
  ui_story_5020_50200401_28_dialog_content = "จ-ต้องเลี้ยวขวาต่อไป! ฉันแน่ใจว่าฉันไม่เคยเป็นแบบนี้มาก่อน...",
  ui_story_5020_50200401_29_dialog_content = "...",
  ui_story_5020_50200401_30_dialog_content = "PlayerName, คุณโกหก! สัญชาตญาณของฉันช่างไร้ค่าสิ้นดี!!",
  ui_story_5020_50200401_31_dialog_content = "เฮ้อ ช่างเหอะ",
  ui_story_5020_50200401_32_dialog_content = "แทนที่จะคิดมากให้ปวดหัว ฉันน่าจะโดดลงจากพลับพลาเมฆาแบบที่อาจารย์ทำ",
  ui_story_5020_50200401_33_dialog_content = "เอาล่ะ! แผนนี้เข้าท่าดี!",
  ui_story_5020_50200401_34_dialog_content = "ใช่แล้ว... โดดจากบนนี้...",
  ui_story_5020_50200401_35_dialog_content = "ดูไม่สูงเลย!",
  ui_story_5020_50200401_36_dialog_content = "อาจารย์คงใช้ต้นซากุระนั่นหักล้ม... ใช่ไหม?",
  ui_story_5020_50200401_37_dialog_content = "เอาล่ะ เจ้าซากุระ... พร้อมรึยัง ฉันมาแล้ว!",
  ui_story_5020_50200401_38_dialog_content = "...",
  ui_story_5020_50200401_39_dialog_content = "ฉัน... ฉันไม่ไหวแล้ว!!",
  ui_story_5020_50200401_40_dialog_content = "ฉันไม่รู้ว่าอาจารย์ทำได้อย่างไร แต่ฉันแน่ใจว่าทำไม่ได้!",
  ui_story_5020_50200401_41_dialog_content = "ฉันหมายความว่าดูสิว่าฉันอยู่ไกลแค่ไหน ...",
  ui_story_5020_50200401_41X1_dialog_content = "นักรบที่แท้จริงจะไม่ทำอะไรที่พวกเขาไม่แน่ใจ!",
  ui_story_5020_50200401_41X2_dialog_content = "ต-ต้องลองหาดูก่อน ว่ามีเชือกหรืออะไรมาช่วยโหนลงไปได้บ้าง...",
  ui_story_5020_50200401_41X3_dialog_content = "อ๊ะ... ที่เดียวที่จะซ่อนของได้ในห้องนี้ ก็มีแต่...",
  ui_story_5020_50200401_41X4_dialog_content = "ตู้เสื้อผ้านี่แหละ!",
  ui_story_5020_50200401_41X5_dialog_content = "หืมม?",
  ui_story_5020_50200401_41X6_dialog_content = "อะไรกันนี่?",
  ui_story_5020_50200401_41X7_dialog_content = "ความรู้สึกแบบนี้ ทำไมมัน<color=#FFB400>คุ้น ๆ</color>?",
  ui_story_5020_50200401_41X8_dialog_content = "ช่างมันก่อน! ต้องเปิดตู้เสื้อผ้าแล้วหาดูว่ามีเชือกมั้ย!",
  ui_story_5020_50200401_42_dialog_content = "<color=#e8d9bb>กริ๊ง...</color>",
  ui_story_5020_50200401_43_dialog_content = "<color=#e8d9bb>กริ๊ง... กริ๊ง...</color>",
  ui_story_5020_50200401_44_dialog_content = "หา?!",
  ui_story_5020_50200401_45_dialog_content = "กระดิ่งคางุระเหรอ?",
  ui_story_5020_50200401_46_dialog_content = "<color=#e8d9bb>ติ๊ง...ติ๊ง...ติ๊ง!</color>",
  ui_story_5020_50200401_47_dialog_content = "อ๋อ... <color=#FFB400>โมบาย</color>ที่แขวนอยู่ในตู้นี่เอง",
  ui_story_5020_50200401_48_dialog_content = "แปลกแฮะ... ทำไมเสียงเหมือนกระดิ่งคางุระจัง?",
  ui_story_5020_50200401_49_dialog_content = "เดี๋ยวนะ... นี่มัน...",
  ui_story_5020_50200401_50_dialog_content = "<color=#e8d9bb>10 ปีที่แล้ว</color>",
  ui_story_5020_50200401_51_dialog_content = "<color=#e8d9bb>กริ๊ง... กริ๊ง...</color>",
  ui_story_5020_50200401_52_dialog_content = "จุ๊! เงียบนะยะ! อยู่ข้างในและอย่าส่งเสียง!",
  ui_story_5020_50200401_53_dialog_content = "เกิดอะไรขึ้นข้างนอก สึกิ? ฉันกลัว...",
  ui_story_5020_50200401_54_dialog_content = "คุณจะไม่ทิ้งฉันไว้ที่นี่คนเดียวใช่ไหม",
  ui_story_5020_50200401_55_dialog_content = "ได้โปรดเถอะ สึกิ...",
  ui_story_5020_50200401_56_dialog_content = "เพียงแค่นอนสักครู่ภายในนี้ <color=#FFB400>ตู้เสื้อผ้า</color>และทุกอย่างจะดีเมื่อคุณตื่นขึ้น ฉันสัญญา.",
  ui_story_5020_50200401_57_dialog_content = "สึกิ...",
  ui_story_5020_50200401_58_dialog_content = "<size=45>เปิดเดี๋ยวนี้!</size>",
  ui_story_5020_50200401_58X1_dialog_content = "(มีคนจะพังเข้ามา!)",
  ui_story_5020_50200401_58X2_dialog_content = "ป้องกันประตูไว้ให้ดี! อย่าให้สิ่งชั่วร้ายเข้ามาได้เด็ดขาด!",
  ui_story_5020_50200401_58X3_dialog_content = "\"ข้าขอกล่าวบทสวดแห่งหยินหยาง เพื่อชี้นำดวงวิญญาณของเจ้ากลับสู่สถานที่อันสมควร...\"",
  ui_story_5020_50200401_58X4_dialog_content = "<color=#e8d9bb>กริ๊ง... กริ๊ง...</color>",
  ui_story_5020_50200401_58X5_dialog_content = "(เสียงกระดิ่งคางุระที่สยบภูตผี...!)",
  ui_story_5020_50200401_58X6_dialog_content = "<color=#e8d9bb>ปัง!!!</color>",
  ui_story_5020_50200401_59_dialog_content = "หยุดนะ! ใครกันน่ะ?! เข้ามา...",
  ui_story_5020_50200401_60_dialog_content = "<size=45>ไปให้พ้น!</size>",
  ui_story_5020_50200401_61_dialog_content = "(เสียงนั่น... อาจารย์?)",
  ui_story_5020_50200401_62_dialog_content = "นากิ?",
  ui_story_5020_50200401_63_dialog_content = "คุณอย่ากล้าเรียกฉันว่า <color=#FFB400>พระนางพญา</color>.",
  ui_story_5020_50200401_64_dialog_content = "คุณไม่สมควรได้รับมัน",
  ui_story_5020_50200401_65_dialog_content = "ตอบฉันมา... ทำไมเธอถึงโน้มน้าวให้โชคุยูล้มเลิกความตั้งใจ?",
  ui_story_5020_50200401_66_dialog_content = "เธอสัญญากับฉันไว้ว่าจะเป็นมิโกะที่ทำเพื่อประชาชน! เพื่อให้ทุกคนบนเกาะเมฆามีชีวิตที่ดี!",
  ui_story_5020_50200401_67_dialog_content = "...",
  ui_story_5020_50200401_68_dialog_content = "ฉันถามเธออยู่นะ!",
  ui_story_5020_50200401_69_dialog_content = "?!",
  ui_story_5020_50200401_70_dialog_content = "สึกิ!",
  ui_story_5020_50200401_71_dialog_content = "เจ้าเสียสติไปแล้วหรือไง นากิ?!",
  ui_story_5020_50200401_72_dialog_content = "เธอเป็นพี่สาวของเจ้านะ!",
  ui_story_5020_50200401_73_dialog_content = "ทหาร! ฆ่าเธอซะ!",
  ui_story_5020_50200401_74_dialog_content = "อย่านะ...!",
  ui_story_5020_50200401_75_dialog_content = "ได้โปรดเถอะ ท่านคุโบ... อย่าทำเช่นนี้เลย...",
  ui_story_5020_50200401_76_dialog_content = "แม่น้ำเบื้องล่างไหลผ่านนาข้าวทางตะวันตกของเมือง...",
  ui_story_5020_50200401_77_dialog_content = "สวนที่อยู่บริเวณเชิงเขาด้านตะวันตก... ดอกซากุระสีขาวที่นั่นคงจะบานเต็มที่แล้ว...",
  ui_story_5020_50200401_78_dialog_content = "โปรดอย่าทำให้กลีบดอกสวยงามเปื้อนเลือด...",
  ui_story_5020_50200401_79_dialog_content = "เมื่อฉันจากไปแล้ว... โปรดฝังร่างของฉันไว้ใต้ต้นซากุระขาวเหล่านั้นด้วย...",
  ui_story_5020_50200401_80_dialog_content = "สัญญากับฉันได้ไหม... ท่านคุโบ?",
  ui_story_5020_50200401_81_dialog_content = "อดทนไว้ สึกิ! ข้าสัญญาว่าข้า...",
  ui_story_5020_50200401_82_dialog_content = "\"ข้าขอกล่าวบทสวด... แห่งหยินหยาง...\"",
  ui_story_5020_50200401_83_dialog_content = "นี่... ทำอะไรของเจ้าน่ะ?!",
  ui_story_5020_50200401_84_dialog_content = "สึกิ อย่านะ! ร่างกายของเจ้าแบกรับมันไม่ไหวหรอก!",
  ui_story_5020_50200401_85_dialog_content = "\"ขอบทเพลงนี้...\"",
  ui_story_5020_50200401_86_dialog_content = "\"จงชี้นำทุกดวงวิญญาณกลับสู่สถานที่อันสมควร\"",
  ui_story_5020_50200401_87_dialog_content = "อึก...!",
  ui_story_5020_50200401_88_dialog_content = "...",
  ui_story_5020_50200401_89_dialog_content = "...",
  ui_story_5020_50200401_90_dialog_content = "หลังจากทุกอย่างที่เกิดขึ้น เจ้ายังคิดจะปกป้องมันอีกรึ...?",
  ui_story_5020_50200401_91_dialog_content = "ทหาร...",
  ui_story_5020_50200401_92_dialog_content = "ตั้งแต่นี้ไป กองทัพปีศาจจะปกป้องดินแดนผนึกแห่งนี้ตราบจนนิรันดร์",
  ui_story_5020_50200401_93_dialog_content = "จงขังผู้หญิงชั่วคนนี้ไว้ อย่าให้มันได้เห็นเดือนเห็นตะวันอีก!",
  ui_story_5020_50200401_94_dialog_content = "ขอรับ!",
  ui_story_5020_50200401_95_dialog_content = "ส่วนสึกิ... ข้าจะทำตามความปรารถนาของเธอ",
  ui_story_5020_50200401_96_dialog_content = "น้อมรับบัญชา",
  ui_story_5020_50200401_97_dialog_content = "ส่วนเจ้า...",
  ui_story_5020_50200401_98_dialog_content = "สึกิเพียงแค่อยากจะปกป้องเจ้า แต่เจ้ากลับสังหารเธอเป็นการตอบแทน... เจ้าไม่มีความละอายใจเลยหรือ? เจ้ามันไม่มีหัวใจหรือไงกัน?!",
  ui_story_5020_50200401_99_dialog_content = "ฉันไม่จำเป็นต้องให้เธอปกป้องตั้งแต่แรกแล้ว และแกก็จะต้องตายตามเธอไป",
  ui_story_5020_50200401_100_dialog_content = "เจ้าน่ะดวงตามืดบอดมาตลอด ไม่เคยมองเห็นความจริงเลย นากิ...",
  ui_story_5020_50200401_101_dialog_content = "เจ้าไม่เคยเข้าใจถึงเหตุผล ที่สึกิเลือกจะต่อสู้เคียงข้างข้า",
  ui_story_5020_50200401_102_dialog_content = "ในตอนนั้น ข้าให้อนุญาตโดยไม่กล่าววาจาใด ๆ เปิดโอกาสให้เธอได้รับรู้สิ่งที่ไม่ควรจะล่วงรู้",
  ui_story_5020_50200401_103_dialog_content = "การ \"ขับไล่ภูตผี\" กับ \"ควบคุมภูตผี\" ที่จริงแล้วเป็นสิ่งที่ไม่ได้แตกต่างกันขนาดนั้น แต่ความแตกต่างนี้ก็สะท้อนถึงกฎระเบียบและประเพณีของเกาะเมฆาที่มีมาช้านาน",
  ui_story_5020_50200401_104_dialog_content = "เธอเข้าใจภาระหน้าที่ของข้าเป็นอย่างดี ด้วยเหตุนี้ เธอจึงภักดีกับข้า เชื่อใจข้า และอุทิศทั้งชีวิตเพื่อรักษาความสงบสุขของเกาะเมฆา",
  ui_story_5020_50200401_105_dialog_content = "แม้จะรู้และเข้าใจทุกอย่าง แต่เธอก็ยังเมตตาและเลือกที่จะปกป้องพวกป่าเถื่อนโง่เขลาอย่างเจ้า",
  ui_story_5020_50200401_106_dialog_content = "ไม่... แกเข้าใจผิดแล้ว!",
  ui_story_5020_50200401_107_dialog_content = "แล้วสิ่งที่เจ้าทำมันหมายความว่ายังไง?",
  ui_story_5020_50200401_108_dialog_content = "สายสัมพันธ์พี่น้องที่เจ้าตัดมันจนขาดสะบั้นน่ะ?!",
  ui_story_5020_50200401_109_dialog_content = "เธออายุเท่าคุณ แต่ดวงตาของเธอเต็มไปด้วยความเห็นอกเห็นใจและความเข้าใจอยู่เสมอ มีสติปัญญาล้ำเลิศเกินกว่าอายุของเธอ...",
  ui_story_5020_50200401_110_dialog_content = "และยัง... คุณฆ่าเธอ!!!",
  ui_story_5020_50200401_111_dialog_content = "คุณเอาชีวิตของเธอ ความหวังและความฝันของเธอที่ Cloud Island ไปด้วย!!!",
  ui_story_5020_50200401_112_dialog_content = "เจ้าไม่มีสิทธิ์ที่จะได้อยู่บนโลกนี้ต่อไปด้วยซ้ำ!!!",
  ui_story_5020_50200401_113_dialog_content = "...",
  ui_story_5020_50200401_114_dialog_content = "<size=33>ทำไมเธอเลือกที่จะปกป้องเจ้า แม้ว่านั่นจะต้องแลกด้วยชีวิตของเธอเอง...?!</size>",
  ui_story_5020_50200401_115_dialog_content = "ช่างเป็นเกียรติจริง ๆ ที่ได้ฟังสุนทรพจน์อันแสนประทับใจจากแก!",
  ui_story_5020_50200401_116_dialog_content = "พลิกเรื่องราวการเอาเปรียบเธอให้กลายเป็นเรื่องราวแห่งความไว้วางใจและความเข้าใจ...",
  ui_story_5020_50200401_117_dialog_content = "แกหลอกเธอด้วยคำพูดพวกนั้นใช่มั้ย?!",
  ui_story_5020_50200401_118_dialog_content = "เธอเป็นคนที่มีสติปัญญาเฉลียวฉลาดล้ำเลิศ",
  ui_story_5020_50200401_119_dialog_content = "ในใจของเธอ เธอรู้ว่าเป้าหมายของเราทั้งคู่คือปกป้องสถานที่แห่งนี้ไม่ว่าจะด้วยวิธีใดก็ตาม เช่นนี้ คำว่าแสวงประโยชน์จึงไม่มีอยู่ระหว่างเรา",
  ui_story_5020_50200401_120_dialog_content = "... เธอใช้พลังผนึกเจ้าไว้สินะ แบบนี้เองรึ ก็เป็นโทษทัณฑ์ที่สาสมแล้ว",
  ui_story_5020_50200401_121_dialog_content = "จากนี้ไปเจ้าจะได้ใช้ชีวิตทุกวันคืนไปกับความเกลียดชังและความโกรธแค้น",
  ui_story_5020_50200401_122_dialog_content = "ฉันสาบานว่าจะฆ่าแกให้ได้!",
  ui_story_5020_50200401_123_dialog_content = "เราจะได้เห็นกัน ว่าวันนั้นจะมาถึงไหม",
  ui_story_5020_50200401_124_dialog_content = "สึกิ...?",
  ui_story_5020_50200401_125_dialog_content = "อาจารย์... เป็นคน<size=45>ฆ่ามิโกะ</size>งั้นเหรอ?!",
  ui_story_5020_50200401_126_dialog_content = "แต่อาจารย์ของฉันไม่ใช่คนแบบนั้นนี่...",
  ui_story_5020_50200401_127_dialog_content = "ในอดีตแกก็หลอกใช้เธอแบบนี้เหมือนกันใช่มั้ย?",
  ui_story_5020_50200401_128_dialog_content = "สาวน้อย... เธอน่ะก็เป็นแค่เครื่องมือที่เอามาแทนของเก่า",
  ui_story_5020_50200401_129_dialog_content = "รู้มั้ยว่าเกิดอะไรขึ้นกับมิโกะคนก่อน?",
  ui_story_5020_50200401_130_dialog_content = "หุบปากนะ!",
  ui_story_5020_50200401_131_dialog_content = "ทหาร จับเธอซะ!",
  ui_story_5020_50200401_132_dialog_content = "ไม่... นี่ต้องเป็นเรื่องเข้าใจผิดแน่ ๆ",
  ui_story_5020_50200401_133_dialog_content = "โอย... หัวฉัน...",
  ui_story_5020_50200401_134_dialog_content = "ฉันต้องกลับไปเจอกับ PlayerName เพื่อเล่าทุกอย่างให้ฟัง!",
  ui_story_5020_50200501_1_dialog_content = "เฮ้! ปล่อยเราไป! เราใช้คำพูดของเราไม่ได้เหรอ?",
  ui_story_5020_50200501_2_dialog_content = "ใช่! นี่ต้องเป็นเรื่องเข้าใจผิดแน่ ๆ!",
  ui_story_5020_50200501_3_dialog_content = "...",
  ui_story_5020_50200501_4_dialog_content = "แถวนี้น่าจะปลอดภัยแล้วล่ะ",
  ui_story_5020_50200501_5_dialog_content = "ไปช่วยชาวเมืองปรับตัวกับที่นี่เถอะ",
  ui_story_5020_50200501_6_dialog_content = "ขอรับ!",
  ui_story_5020_50200501_7_dialog_content = "ส่วนเจ้าเด็กเอะอะโวยวายพวกนี้...",
  ui_story_5020_50200501_8_dialog_content = "เอาไปมัดกับเสาก่อนก็แล้วกัน",
  ui_story_5020_50200501_9_dialog_content = "ว่าไงนะ!?",
  ui_story_5020_50200501_10_dialog_content = "ขอรับ!",
  ui_story_5020_50200501_11_dialog_content = "เฮ้ย! หยุดดิ้นได้แล้ว!",
  ui_story_5020_50200501_12_dialog_content = "หนอย... เจ้าพวกนี้...",
  ui_story_5020_50200501_13_dialog_content = "เดี๋ยวสิ ผมไม่เข้าใจเลย!",
  ui_story_5020_50200501_14_dialog_content = "พวกคุณกำลังปกป้องพลเรือนใช่ไหม? เราก็เช่นกัน! ไม่ได้หมายความว่าเราอยู่ในหน้าเดียวกัน?",
  ui_story_5020_50200501_15_dialog_content = "เข้าใจผิดแล้ว",
  ui_story_5020_50200501_16_dialog_content = "พวกแกอยู่กับมิโกะ ซึ่งเป็นศัตรูตัวฉกาจของเรา",
  ui_story_5020_50200501_17_dialog_content = "มิโกะเหรอ? เธอไปเกี่ยวอะไรด้วยล่ะ...?",
  ui_story_5020_50200501_18_dialog_content = "เข้าใจแล้ว",
  ui_story_5020_50200501_19_dialog_content = "ถ้าจำไม่ผิด อาเมะโมริก็เป็นพวกเดียวกับคุณ ถูกต้องไหม?",
  ui_story_5020_50200501_20_dialog_content = "รู้ฐานะของตัวเองหน่อย มิโกะ",
  ui_story_5020_50200501_21_dialog_content = "คุณไม่อยู่ในฐานะที่จะถามคำถามใดๆ กับเรา",
  ui_story_5020_50200501_22_dialog_content = "หึหึ... ฉันก็ไม่รู้ฐานะของตัวเองจริง ๆ นั่นแหละ",
  ui_story_5020_50200501_23_dialog_content = "บางทีเราควรรอให้คุณแนะนำตัวเอง?",
  ui_story_5020_50200501_24_dialog_content = "บอกเราทีสิ ว่ากองพลโชคุยูคืออะไร?",
  ui_story_5020_50200501_25_dialog_content = "ฮ่าฮ่าฮ่าฮ่า! เป็นคนที่มีอารมณ์ขันจริง ๆ",
  ui_story_5020_50200501_26_dialog_content = "ใครจะรู้ว่าวันหนึ่งจะมาถึงเมื่อนักบวชหญิงแห่งเกาะเมฆาไม่รู้ด้วยซ้ำว่าวิสป์คือใคร",
  ui_story_5020_50200501_27_dialog_content = "ใครจะไปรู้ บางทีในอีกไม่กี่ชั่วอายุคน แม้แต่ Cloud Island ก็จะถูกลืม!",
  ui_story_5020_50200501_28_dialog_content = "ในท้ายที่สุด มันก็ไม่ได้สำคัญอะไรสำหรับคุณ",
  ui_story_5020_50200501_29_dialog_content = "ในฐานะมิโกะ เธอก็แค่อยู่ในปราสาทหลังโตแสนสุขสบาย แล้วก็คอยเอาอกเอาใจท่านคุโบของเธอ",
  ui_story_5020_50200501_30_dialog_content = "...",
  ui_story_5020_50200501_31_dialog_content = "นี่มันเกินไปแล้วนะ!",
  ui_story_5020_50200501_32_dialog_content = "รินเนะปกป้องชาวเมืองโคฟุโจมาตลอด! พวกคุณก็เห็นกับตาไม่ใช่เหรอ!",
  ui_story_5020_50200501_33_dialog_content = "ปกป้องงั้นเหรอ? คนนอกน่ะเก็บคำพูดสวยหรูพวกนั้นไปเถอะ",
  ui_story_5020_50200501_34_dialog_content = "เธอไม่ได้เป็นอะไรมากไปกว่าแมวบ้าน ไล่ฆ่าหนูที่เลี้ยงในบ้าน",
  ui_story_5020_50200501_35_dialog_content = "นั่นไม่ใช่การป้องกัน มันคือการแสดง",
  ui_story_5020_50200501_36_dialog_content = "การแสดง? หมายความว่าไงกัน...?",
  ui_story_5020_50200501_37_dialog_content = "ขอถามอะไรหน่อยสิ เธอคิดว่าผีพวกนี้มาจากไหน?",
  ui_story_5020_50200501_38_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50200501_39_dialog_content = "คุณเป็นผู้เชี่ยวชาญในเรื่องนี้ใช่ไหม นักบวชหญิง สนใจที่จะอธิบาย?",
  ui_story_5020_50200501_40_dialog_content = "... เมื่อมีพลังหยินมากมาย วิญญาณของคนตายไม่สามารถพักผ่อนได้ และกลับมาเป็นผีพยาบาทแทน",
  ui_story_5020_50200501_41_dialog_content = "บอกเราทีว่าพลังหยินที่มีอยู่มากมายนี้มาจากไหน? ขาดอากาศ?",
  ui_story_5020_50200501_42_dialog_content = "...",
  ui_story_5020_50200501_43_dialog_content = "เงียบไปเลยงั้นรึ? ไม่ต้องห่วง ฉันรู้คำตอบอยู่แล้ว มี<color=#FFB400>ใครบางคน</color>อยู่เบื้องหลังเรื่องนี้",
  ui_story_5020_50200501_44_dialog_content = "ตั้งแต่สมัยโบราณ Cloud Island เป็นที่อยู่ของสามคน <color=#FFB400>สิ่งประดิษฐ์ทางจิตวิญญาณ</color>.",
  ui_story_5020_50200501_45_dialog_content = "<color=#FFB400>ชิ้นแห่งสวรรค์</color>ดาบสังหารภูติผีและแหล่งพลังหยางหายไปในขณะนี้",
  ui_story_5020_50200501_46_dialog_content = "<color=#FFB400>กบฏและ Ryojin</color>หยกที่สร้างความสมดุลระหว่างหยินและหยางอยู่ในความครอบครองของ Wisp",
  ui_story_5020_50200501_47_dialog_content = "และ <color=#FFB400>กระจกเมฆ</color>แหล่งที่มาของพลังงานหยินอยู่ในมือของนายพลมาโดยตลอด",
  ui_story_5020_50200501_48_dialog_content = "นั่นคือกระจกที่โชกุนแย่งจากรินเนะไปนี่นา...",
  ui_story_5020_50200501_49_dialog_content = "\"เมื่อเมฆดำทะมึนบดบังดวงตะวัน ผู้อาศัยในนรกภูมิจักก้าวข้ามสู่โลกของคนเป็น\"",
  ui_story_5020_50200501_50_dialog_content = "สิ่งเดียวที่เรียกภูตผีมากมายขนาดนั้นให้ออกอาละวาดในเมืองได้... ก็มีแต่<color=#FFB400>กระจกเมฆา</color>เท่านั้น",
  ui_story_5020_50200501_51_dialog_content = "บอกฉันสิ คิดว่าใครกันที่อยู่เบื้องหลังเรื่องพวกนี้? ฉันมั่นใจพวกเธอคงจะเดาได้แล้ว!",
  ui_story_5020_50200501_52_dialog_content = "... ที่จริงเราก็ได้ข้อสรุปแบบนั้นเหมือนกัน",
  ui_story_5020_50200501_53_dialog_content = "แต่ยังมีบางเรื่องที่ผมยังคิดไม่ออก",
  ui_story_5020_50200501_54_dialog_content = "ถ้าฟูจิคุโมะสามารถควบคุมภูติผีได้ตามต้องการ ทำไมเขาถึงเลี้ยงและฝึกฝนนักบวชหญิงเพื่อไล่ผีเหล่านั้น?",
  ui_story_5020_50200501_55_dialog_content = "ก็บอกไปแล้วไม่ใช่หรือไง? นั่นมันก็แค่การแสดงเท่านั้น",
  ui_story_5020_50200501_56_dialog_content = "พวกผีถูกเรียกมาสู้รบเพื่อพิชิตศึกสงคราม ส่วนมิโกะมีหน้าที่สยบผู้คนในฐานะเครื่องยึดเหนี่ยวจิตใจ",
  ui_story_5020_50200501_57_dialog_content = "ควบคุมให้ชาวเมืองเชื่อฟังงั้นเหรอ?",
  ui_story_5020_50200501_58_dialog_content = "โชกุนควบคุมภูตผี ปลูกฝังความกลัวในจิตใจของชาวเกาะเมฆา",
  ui_story_5020_50200501_59_dialog_content = "แต่ความกลัวอย่างเดียวไม่อาจปกครองเกาะเมฆาได้ ผู้นำที่เก่งกาจย่อมรู้ดี",
  ui_story_5020_50200501_60_dialog_content = "มิโกะจึงมีบทบาทในเรื่องนี้ พวกเธอได้รับการฝึกฝนให้เผชิญสิ่งที่น่าหวาดกลัวเพื่อประชาชน",
  ui_story_5020_50200501_61_dialog_content = "เมื่อชาวเมืองต้องพึ่งพามิโกะ และมิโกะก็เคารพเชื่อฟังแค่โชกุนเพียงคนเดียว เท่านี้เขาก็กุมอำนาจได้อย่างเบ็ดเสร็จ",
  ui_story_5020_50200501_62_dialog_content = "โชคไม่ดีสำหรับเขา เขาประเมินตัวเองสูงเกินไป",
  ui_story_5020_50200501_63_dialog_content = "ชาวเกาะเมฆาไม่ใช่คนโง่ เราไม่โดนหลอกด้วยลูกไม้ตื้น ๆ แบบนี้อยู่แล้ว",
  ui_story_5020_50200501_64_dialog_content = "มิโกะอย่างเธออ้างว่าการไล่ผีจะนำสมดุลกลับมาสู่ดินแดน... แต่ถึงกระนั้น ทำไมภูตผีก็ยังออกคุกคามผู้คนไม่หยุดหย่อนล่ะ?",
  ui_story_5020_50200501_65_dialog_content = "...",
  ui_story_5020_50200501_66_dialog_content = "พวกเราไม่มีวันลืมหรอก ว่าที่นี่ไม่ได้มีชื่อว่า \"โคฟุโจ\" มาตั้งแต่แรก",
  ui_story_5020_50200501_67_dialog_content = "ไม่ว่าพวกมันจะสร้างปราสาทสักกี่หลัง หรือจะนำทรัพย์สินเงินทองมากองมากมายแค่ไหน...",
  ui_story_5020_50200501_68_dialog_content = "ยังไงพวกมันก็คือผู้รุกรานอยู่วันยังค่ำ",
  ui_story_5020_50200501_69_dialog_content = "Wisp เป็นเพียงผู้พิทักษ์ที่แท้จริงของ Cloud Island",
  ui_story_5020_50200501_70_dialog_content = "เพราะมีเพียงเราเท่านั้นที่เกิดมาในแผ่นดินนี้",
  ui_story_5020_50200501_71_dialog_content = "ผู้รุกราน? พวกคุณมองคนจากเกาะหลักแบบนี้เหรอ...?",
  ui_story_5020_50200501_72_dialog_content = "พวกเธอคงไม่ค่อยรู้ประวัติของเกาะเมฆาเท่าไรสินะ",
  ui_story_5020_50200501_73_dialog_content = "และนั่นสมเหตุสมผล ฉันหมายความว่าคุณเรียนรู้เกี่ยวกับเรื่องนี้ได้จากที่ไหน",
  ui_story_5020_50200501_74_dialog_content = "(ก็รู้มานิดหน่อยจากอันสึกับโมโมะล่ะนะ...)",
  ui_story_5020_50200501_75_dialog_content = "(แต่เรื่องในฝั่งของกองพลโชคุยูอาจจะมีสาระสำคัญที่ต่างกันก็ได้)",
  ui_story_5020_50200501_76_dialog_content = "คุณถูก. เราไม่รู้อะไรเกี่ยวกับ Cloud Island มากนัก เนื่องจากเรามาจากสถานที่ห่างไกล",
  ui_story_5020_50200501_77_dialog_content = "ก็ว่างั้นแหละ เอาเป็นว่าฉันจะเล่าส่วนที่สำคัญให้เอาบุญก็แล้วกัน",
  ui_story_5020_50200501_78_dialog_content = "หลายปีมาแล้ว ก่อนที่ซามูไรของเกาะหลักจะเหยียบเกาะคลาวด์ มันเป็นสถานที่ที่สวยงามกว่าที่เป็นอยู่ในปัจจุบันมาก",
  ui_story_5020_50200501_79_dialog_content = "มันเป็นเกาะที่อุดมสมบูรณ์ ปราศจากความขัดแย้ง แทบไม่ถูกคุกคามจากภูตผีชั่วร้าย",
  ui_story_5020_50200501_80_dialog_content = "กองพลโชคุยูถือกำเนิดมาตั้งแต่ยุคนั้น ภารกิจศักดิ์สิทธิ์ของเราคือการสังหารภูตผีและรักษาความสงบของเกาะเมฆา",
  ui_story_5020_50200501_81_dialog_content = "แต่คนที่ทำลายความสงบสุขในท้ายที่สุดไม่ใช่ผี แต่เป็นสิ่งมีชีวิต",
  ui_story_5020_50200501_82_dialog_content = "ไม่เคยพอใจกับดินแดนที่พวกเขาครอบครองอยู่แล้ว เกาะหลักจึงส่งนายพลคนแรกมายึดครองสถานที่แห่งนี้",
  ui_story_5020_50200501_83_dialog_content = "Wisp ไม่เคยทำสงครามกับคนเป็นมาก่อน แต่พวกเขาก็ยอมเสี่ยงชีวิตเหมือนกัน",
  ui_story_5020_50200501_84_dialog_content = "นายพลเปิดตัวการรณรงค์เพื่อต่อต้าน Cloud Island แต่เขาก็ไม่สามารถผนวกเราทั้งหมดได้",
  ui_story_5020_50200501_85_dialog_content = "แต่วันหนึ่งพวกเขาได้วางแผนแผนการที่น่ารังเกียจที่สุดของพวกเขา พวกเขาเริ่มเรียนรู้วิธีควบคุมผี เพื่อที่พวกเขาจะได้ใช้พลังชั่วร้ายในการต่อสู้",
  ui_story_5020_50200501_86_dialog_content = "ในยุคสมัยนั้น ผีร้ายออกอาละวาดไปทั่วดินแดน",
  ui_story_5020_50200501_87_dialog_content = "เราพังทลายภายใต้การคุกคามของผี พร้อมกับอำนาจอธิปไตยของ Cloud Island หลังจากนั้นไม่นาน นายพลได้สร้าง Koufu-jou ตามแนวมหาสมุทรและกำหนดให้เป็นที่นั่งแห่งอำนาจของเขา",
  ui_story_5020_50200501_88_dialog_content = "เมื่อไม่มีทางเลือกอื่น ไพร่พลที่เหลือของโชคุยูก็จำต้องหลบซ่อนหนีตาย แบกรับความโกรธแค้นที่มีต่อผู้รุกรานเอาไว้ และส่งต่อจากรุ่นสู่รุ่น",
  ui_story_5020_50200501_89_dialog_content = "สิ่งหนึ่งที่เราเรียนรู้จากสงครามก็คือ เราจะต้องรอโอกาสที่เหมาะสมที่สุดซึ่งอาจจะมาเพียงครั้งเดียว มีเพียงวิธีนี้เท่านั้นที่เราจะแย่งชิงเกาะเมฆากลับมาได้",
  ui_story_5020_50200501_90_dialog_content = "(นี่จึงเป็นที่มาของความขัดแย้งบนเกาะเมฆา...?)",
  ui_story_5020_50200501_91_dialog_content = "(ดูเผิน ๆ ก็เป็นแค่การต่อสู้ระหว่างมนุษย์กับภูตผี แต่ที่จริงแล้ว... มันคือสงครามระหว่างสองชนชาติ...)",
  ui_story_5020_50200501_92_dialog_content = "และโอกาสนี้...",
  ui_story_5020_50200501_93_dialog_content = "ก็อาจจะใกล้เข้ามาแล้วล่ะ",
  ui_story_5020_50200501_94_dialog_content = "ชาวเมืองปลอดภัยแล้ว",
  ui_story_5020_50200501_95_dialog_content = "ต่อไปเราจะต้อง...",
  ui_story_5020_50200501_96_dialog_content = "เข้าใจแล้ว ไปคุยกันตรงโน้นเถอะ",
  ui_story_5020_50200501_97_dialog_content = "...",
  ui_story_5020_50200501_98_dialog_content = "คุณคิดว่าประวัติศาสตร์ของเกาะเมฆาที่เขาเล่าเป็นเรื่องจริงรึเปล่า?",
  ui_story_5020_50200501_99_dialog_content = "ไม่รู้สิ... เขาเล่าเยอะเหลือเกิน ฉันยังย่อยได้ไม่หมดเลย...",
  ui_story_5020_50200501_100_dialog_content = "ฉันคิดเสมอว่าฉันกำลังฟังคำสั่งที่ง่ายที่สุด",
  ui_story_5020_50200501_101_dialog_content = "เชื่อฟังพ่อบุญธรรมของฉัน และปกป้องผู้คนใน Koufu-jou",
  ui_story_5020_50200501_102_dialog_content = "แต่ถ้าที่เขาพูดเป็นเรื่องจริง...",
  ui_story_5020_50200501_103_dialog_content = "คำสั่งทั้งสองอย่างก็ขัดกันเองน่ะสิ",
  ui_story_5020_50200501_104_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50200501_105_dialog_content = "ทุกสิ่งที่ฉันทุ่มเทไป... เป็นแค่การแสดงเท่านั้นเองเหรอ?",
  ui_story_5020_50200501_106_dialog_content = "ร-เราไม่ต้องเชื่อทุกอย่างที่เขาพูดก็ได้มั้ง",
  ui_story_5020_50200501_107_dialog_content = "ดูสิ เขายังไม่เข้าใจด้วยซ้ำว่าใครเป็นมิตรหรือศัตรู แถมยังจับเรามัดไว้แบบนี้อีก!",
  ui_story_5020_50200501_108_dialog_content = "จริงมั้ย PlayerName?",
  ui_story_5020_50200501_109_dialog_content = "ทำไมคุณดูเหมือนแบ่งเขต?",
  ui_story_5020_50200501_110_dialog_content = "ชู่ว—",
  ui_story_5020_50200501_111_dialog_content = "ฉันพยายามแอบฟังพวกนั้นคุยกันน่ะ...",
  ui_story_5020_50200501_112_dialog_content = "แอบฟังเหรอ?!",
  ui_story_5020_50200501_113_dialog_content = "น่าสนุกดีนะ! ขอแอบฟังด้วยคนสิ!",
  ui_story_5020_50200501_114_dialog_content = "ได้ เข้ามาใกล้ ๆ สิ",
  ui_story_5020_50200501_115_dialog_content = "อื้ม!",
  ui_story_5020_50200501_116_dialog_content = "เราไม่มีที่ให้หนีแล้ว หัวหน้า",
  ui_story_5020_50200501_117_dialog_content = "บนถนนมีพวกผีเต็มไปหมด เรายังติดต่อกับพรรคพวกที่ประจำอยู่ส่วนอื่นไม่ได้เลย...",
  ui_story_5020_50200501_118_dialog_content = "ฉันเห็น. เราจะไม่ไปไหน และเราจะปกป้องสถานที่นี้ด้วยชีวิตของเรา",
  ui_story_5020_50200501_119_dialog_content = "หัวหน้า คุณบอกว่าท่านอาเมะโมริช่วยท่านแม่ทัพออกมาได้แล้วใช่มั้ย?",
  ui_story_5020_50200501_120_dialog_content = "คิดว่า...เค้าจะมาช่วยเรามั้ย?",
  ui_story_5020_50200501_121_dialog_content = "ไม่มีเหตุผลที่จะต้องกลัว ตราบเท่าที่ Sword of the Underworld ยังมีชีวิตอยู่และมีผีอะไรอีกบ้าง?",
  ui_story_5020_50200501_122_dialog_content = "(อาเมะโมริอยู่ฝั่งเดียวกับพวกกบฏจริง ๆ ด้วย!)",
  ui_story_5020_50200501_123_dialog_content = "(ใช่... ดูเหมือนเธอจะมีตำแหน่งสูงในกองพลโชคุยูซะด้วย)",
  ui_story_5020_50200501_124_dialog_content = "ฟังให้ดีนะ ถ้าเป็นเรื่องสู้รบ โชคุยูไม่จำเป็นต้องให้ใครมาช่วย",
  ui_story_5020_50200501_125_dialog_content = "แม้จะเป็นคนสุดท้ายที่ยืนหยัด แต่ก็ต้องสู้จนถึงที่สุด",
  ui_story_5020_50200501_126_dialog_content = "หมายความว่า...",
  ui_story_5020_50200501_127_dialog_content = "ท่านแม่ทัพกับท่านอาเมะโมริมีธุระสำคัญจะต้องจัดการ",
  ui_story_5020_50200501_128_dialog_content = "ฉันไม่กังวลเรื่องนี้แม้แต่นิดเดียว และพวกนายก็ไม่จำเป็นต้องกังวลด้วย",
  ui_story_5020_50200501_129_dialog_content = "(จริงสิ... อยากรู้จังว่าอาเมะโมริเป็นยังไงบ้าง...)",
  ui_story_5020_50200501_130_dialog_content = "(ไม่ต้องห่วงหรอกน่า เธอไม่เป็นไรหรอก พวกเราก็เห็นแล้วนี่ว่าเธอแข็งแกร่งแค่ไหน)",
  ui_story_5020_50200501_131_dialog_content = "...",
  ui_story_5020_50200501_132_dialog_content = "หัวหน้า ทุกคนเบาใจอยู่แล้วที่ได้รู้ว่าท่านแม่ทัพปลอดภัย",
  ui_story_5020_50200501_133_dialog_content = "เพียงแต่ว่า... พวกเราทุกคนยังไม่มีใครได้เห็นหน้าท่านแม่ทัพเลย",
  ui_story_5020_50200501_134_dialog_content = "จนคนส่วนนึงของเราเริ่มสงสัยแล้วว่าข่าวนั่นเป็นเรื่องจริงรึเปล่า",
  ui_story_5020_50200501_135_dialog_content = "แถมบางคนยังบอกอีกว่า...",
  ui_story_5020_50200501_136_dialog_content = "หลังจากผ่านไปสิบปี เธอก็ลืมเรื่อง Wisp ไปเสียหมด...",
  ui_story_5020_50200501_137_dialog_content = "...",
  ui_story_5020_50200501_138_dialog_content = "พอได้แล้ว",
  ui_story_5020_50200501_139_dialog_content = "<color=#e8d9bb>ตูม!</color>",
  ui_story_5020_50200501_140_dialog_content = "(?!)",
  ui_story_5020_50200501_141_dialog_content = "อะไรน่ะ?",
  ui_story_5020_50200501_142_dialog_content = "<color=#e8d9bb>เปรี้ยง!</color>",
  ui_story_5020_50200501_143_dialog_content = "(เสียงใกล้มาก! เหมือนจะมาจากอีกฝั่งของผนังนะ!)",
  ui_story_5020_50200501_144_dialog_content = "เตรียมตัวต่อสู้!",
  ui_story_5020_50200501_145_dialog_content = "<color=#e8d9bb>ปัง!!!</color>",
  ui_story_5020_50200501_146_dialog_content = "<anim type=Shake><size=45>กรรรร!!</size></anim>",
  ui_story_5020_50200501_147_dialog_content = "ทำไมถึงหาเราเจอเร็วจัง...?",
  ui_story_5020_50200501_148_dialog_content = "อา ฉันคิดว่าคงเป็นแค่เรื่องของเวลาเท่านั้น",
  ui_story_5020_50200501_149_dialog_content = "พี่น้องโชคุยูทั้งหลาย!",
  ui_story_5020_50200501_150_dialog_content = "ครับ!!!",
  ui_story_5020_50200501_151_dialog_content = "จงรวบรวมความกล้าที่มี!",
  ui_story_5020_50200501_152_dialog_content = "เราจะส่งผีร้ายพวกนี้กลับนรกให้หมด!",
  ui_story_5020_50200501_153_dialog_content = "ท่าไม่ดีแฮะ... พวกผีเจอเราแล้ว!",
  ui_story_5020_50200501_154_dialog_content = "รู้แล้วล่ะ! เราจะทำไงดี?!",
