  ui_story_5020_50200501_162_dialog_content = "<color=#e8d9bb>ปัง!!!</color>",
  ui_story_5020_50200501_163_dialog_content = "<anim type=Shake>กรร...</anim>",
  ui_story_5020_50200501_164_dialog_content = "ไม่นะ! ทำไมต้องเป็นเวลาแบบนี้ด้วย...",
  ui_story_5020_50200501_165_dialog_content = "มันใกล้เข้ามาแล้ว!",
  ui_story_5020_50200501_166_dialog_content = "ถึงฉันจะเรียกนักรบโชคุยูได้... เขาจะมาช่วยเราทันมั้ยนะ?",
  ui_story_5020_50200501_167_dialog_content = "ว่าไงนะ!",
  ui_story_5020_50200501_168_dialog_content = "หึหึ... แค่ให้ใครก็ได้มาปล่อยเราใช่มั้ย?",
  ui_story_5020_50200501_169_dialog_content = "ถ้าคนของโชคุยูไม่อยากช่วย เราก็คงต้องให้เจ้าพวกนั้นช่วย",
  ui_story_5020_50200501_170_dialog_content = "สิ่งนั้น? เดี๋ยวก่อน คุณไม่ได้หมายความว่า...",
  ui_story_5020_50200501_170X1_dialog_content = "<anim type=Shake>กร๊ากกก...</anim>",
  ui_story_5020_50200501_170X2_dialog_content = "ปล่อยให้ผีตัดเชือก?! ฉันคิดว่าเราจะโดนหั่นก่อน!",
  ui_story_5020_50200501_170X3_dialog_content = "ถ้าอย่างนั้นคุณควรอยู่ต่ำสักครู่",
  ui_story_5020_50200501_171_dialog_content = "<color=#e8d9bb>ผัวะ!</color>",
  ui_story_5020_50200501_172_dialog_content = "<anim type=Shake>อาาา...</anim>",
  ui_story_5020_50200501_173_dialog_content = "เห็นมั้ย?",
  ui_story_5020_50200501_174_dialog_content = "บางครั้งพวกผีก็เชื่อฟังดีกว่าคนอีกนะ",
  ui_story_5020_50200502_1_dialog_content = "หัวหน้า! พวกผีบุกมาจากทุกทิศเลย!",
  ui_story_5020_50200502_2_dialog_content = "เราโดนล้อมแล้ว!",
  ui_story_5020_50200502_3_dialog_content = "การโจมตีอย่างกะทันหันของพวกเขาในตอนนี้คือการซื้อเวลาเพื่อตั้งล้อม...",
  ui_story_5020_50200502_4_dialog_content = "ฉลาดคิดกลยุทธ์แบบนี้ได้ แสดงว่าต้องมีคนอยู่เบื้องหลังแน่นอน",
  ui_story_5020_50200502_5_dialog_content = "หมายความว่าไงน่ะ...?",
  ui_story_5020_50200502_6_dialog_content = "ตลอดหลายปีที่เราต่อสู้กับภูตผี กองพลโชคุยูเคยโดนมันต้อนจนมุมแบบนี้รึเปล่าล่ะ?",
  ui_story_5020_50200502_7_dialog_content = "พวกมันไม่ได้รับรู้อะไรไวขนาดนั้น ถึงการต่อสู้จะดึงดูดพวกมัน แต่ยังไงก็ไม่มีทางเร็วขนาดนี้แน่",
  ui_story_5020_50200502_8_dialog_content = "และที่พวกมันต้อนเราจนมุมได้... ก็แสดงว่ามันรู้ตำแหน่งของเรา รวมตัวกัน ล้อมรอบพวกเรา และจากนั้นค่อยบุกเข้ามาพร้อมกัน",
  ui_story_5020_50200502_9_dialog_content = "ต้องมีใครบางคนควบคุมการกระทำของพวกมันแน่นอน",
  ui_story_5020_50200502_10_dialog_content = "ดูเหมือนว่าในที่สุด... โชกุนก็ลงมือแล้วสินะ",
  ui_story_5020_50200502_11_dialog_content = "ถ้างั้นเราทำยังไงกันดีล่ะ หัวหน้า?",
  ui_story_5020_50200502_12_dialog_content = "เราต้องตั้งรับสถานการณ์ให้ได้ก่อน เพื่อที่เราจะหาทางผ่านด่านของพวกเขาได้",
  ui_story_5020_50200502_13_dialog_content = "อย่างน้อยที่สุด เราต้องพาพลเรือนออกจาก Koufu-jou อย่างปลอดภัย...",
  ui_story_5020_50200502_14_dialog_content = "(ระวังข้างหลัง!)",
  ui_story_5020_50200502_15_dialog_content = "?!",
  ui_story_5020_50200502_16_dialog_content = "เมื่อกี้ใครพูดน่ะ?!",
  ui_story_5020_50200502_17_dialog_content = "(ผมเอง! คนนอกที่คุณจับมัดไว้ไงล่ะ!)",
  ui_story_5020_50200502_18_dialog_content = "แกหนีออกมาได้ยังไงน่ะ?",
  ui_story_5020_50200502_19_dialog_content = "ถ้ากล้าพอจะมาคุยกัน ก็เลิกทำตัวลับ ๆ ล่อ ๆ แล้วก็ออกมาสิ!",
  ui_story_5020_50200502_20_dialog_content = "(เอ่อ... ที่จริงผมไม่ได้อยู่ใกล้กับคุณหรอกนะ)",
  ui_story_5020_50200502_21_dialog_content = "(ฉันใช้ความสามารถทางจิตเพื่อสื่อสารกับคุณ)",
  ui_story_5020_50200502_22_dialog_content = "หมายความว่าไงน่ะ?",
  ui_story_5020_50200502_23_dialog_content = "(เอ่อ มันก็คือ... อ่า ช่างเถอะ นั่นไม่สำคัญหรอก)",
  ui_story_5020_50200502_24_dialog_content = "(เรื่องสำคัญก็คือ ผมกับเพื่อน ๆ ช่วยคุณได้นะ!)",
  ui_story_5020_50200502_25_dialog_content = "ช่วยเรอะ? หึ! กองพลโชคุยูไม่เคยขอความช่วยเหลือจากใคร ยิ่งนักโทษอย่างพวกแกยิ่งแล้วใหญ่!",
  ui_story_5020_50200502_26_dialog_content = "(เมื่อเหล่าภูตผีเข้าจู่โจมที่นี่ ถึงเวลาแล้วหรือยังที่จะต้องทำตัวให้สูงส่งและทรงพลัง?)",
  ui_story_5020_50200502_27_dialog_content = "หนอย แก...!",
  ui_story_5020_50200502_28_dialog_content = "(มีพวกผีบุกมาจากถนนทางด้านขวา!)",
  ui_story_5020_50200502_29_dialog_content = "ขวางั้นเรอะ?",
  ui_story_5020_50200502_30_dialog_content = "<anim type=Shake>กรร...</anim>",
  ui_story_5020_50200502_31_dialog_content = "เป็นอย่างที่พูดจริง ๆ ด้วย...",
  ui_story_5020_50200502_32_dialog_content = "ชิดขวา! ทหาร บุก!",
  ui_story_5020_50200502_33_dialog_content = "(เอ่อ ที่จริง... พวกเขามาจากทางซ้ายด้วย)",
  ui_story_5020_50200502_34_dialog_content = "<anim type=Shake>กรร...</anim>",
  ui_story_5020_50200502_35_dialog_content = "อะไรเนี่ย... แล้วทำไมไม่บอกแต่แรกล่ะ...",
  ui_story_5020_50200502_36_dialog_content = "(เพราะเราจัดการทางฝั่งนี้ให้คุณได้น่ะสิ)",
  ui_story_5020_50200502_37_dialog_content = "ด้วยความยินดี!",
  ui_story_5020_50200502_38_dialog_content = "ทำไมถึงช่วยพวกเราล่ะ?",
  ui_story_5020_50200502_39_dialog_content = "มีมิโกะอยู่ด้วย โชกุนไม่น่าจะยุ่งอะไรกับพวกเธอนี่นา",
  ui_story_5020_50200502_40_dialog_content = "(มันเป็นเรื่องยาว แต่เราไม่ได้อยู่ในเงื่อนไขที่ดีที่สุดกับคนทั่วไปในตอนนี้...)",
  ui_story_5020_50200502_41_dialog_content = "หมายความว่าไง?",
  ui_story_5020_50200502_42_dialog_content = "(เราเพิ่งสู้กันเมื่อไม่นานมานี้... เรื่องมันอธิบายลำบากน่ะครับ)",
  ui_story_5020_50200502_43_dialog_content = "(หลังจากได้ฟังเรื่องของพวกคุณแล้ว ผมก็ได้รู้ว่าประวัติของเกาะเมฆามันซับซ้อนกว่าที่คิดไว้มาก)",
  ui_story_5020_50200502_44_dialog_content = "(ในฐานะคนนอก เราไม่มีสิทธิ์ก้าวก่ายปัญหาของคุณ)",
  ui_story_5020_50200502_45_dialog_content = "(แต่การต่อสู้ขับไล่ผีเพื่อปกป้องผู้คน ยังไงก็เป็นสิ่งที่เราควรทำ)",
  ui_story_5020_50200502_46_dialog_content = "(เพราะฉะนั้น อย่างน้อยในตอนนี้เราก็ควรจะร่วมมือกันกำจัดมัน!)",
  ui_story_5020_50200502_47_dialog_content = "...",
  ui_story_5020_50200502_48_dialog_content = "ได้สิ",
  ui_story_5020_50200502_49_dialog_content = "ฉันจะร่วมมือกับพวกเธอไปก่อน",
  ui_story_5020_50200502_50_dialog_content = "รินเนะ! คุณไม่เป็นไรใช่มั้ย?",
  ui_story_5020_50200502_51_dialog_content = "... ฉันไม่เป็นไร ขอบคุณนะ",
  ui_story_5020_50200502_52_dialog_content = "คุณบาดเจ็บตรงไหนรึเปล่าน่ะ คุณรินเนะ?",
  ui_story_5020_50200502_53_dialog_content = "โดยปกติท่านคงไล่ผีเหล่านี้ออกไปหมดแล้ว",
  ui_story_5020_50200502_54_dialog_content = "...",
  ui_story_5020_50200502_55_dialog_content = "ขอโทษที่ทำให้เป็นห่วงนะ",
  ui_story_5020_50200502_56_dialog_content = "ฉันแค่... จิตใจไม่อยู่กับเนื้อกับตัวน่ะ",
  ui_story_5020_50200502_57_dialog_content = "เพราะเรื่องที่หัวหน้าทหารโชคุยูเล่าให้ฟังเหรอ?",
  ui_story_5020_50200502_58_dialog_content = "ใช่...",
  ui_story_5020_50200502_59_dialog_content = "คำพูดนั้น มันยังวนเวียนอยู่ในหัวของฉัน... \"การแสดง\"...",
  ui_story_5020_50200502_60_dialog_content = "มันคอยรบกวนความคิดของฉัน และฉันไม่สามารถต่อสู้อย่างเต็มกำลังได้",
  ui_story_5020_50200502_61_dialog_content = "ฉัน... ฉันไม่รู้ว่าจะต่อสู้ไปเพื่ออะไร",
  ui_story_5020_50200502_62_dialog_content = "ฉันนึกว่าคุณจะเข้าใจเรื่องนั้นแล้วซะอีก หลังจากที่เราต่อสู้กับโชกุนที่ปราสาทหลัก...",
  ui_story_5020_50200502_63_dialog_content = "ตอนนั้นฉันก็แค่โกรธ ที่จริงก็ไม่ได้เข้าใจอะไรชัดเจนหรอก...",
  ui_story_5020_50200502_64_dialog_content = "แต่ตอนนี้ฉันเข้าใจอย่างแจ่มแจ้งแล้ว",
  ui_story_5020_50200502_65_dialog_content = "เรื่องอะไรเหรอคะ?",
  ui_story_5020_50200502_66_dialog_content = "ตั้งแต่แรก เขาไม่ได้ต้องการจะให้ฉันขับไล่ภูตผีอยู่แล้ว",
  ui_story_5020_50200502_67_dialog_content = "เขาแค่อยากจะใช้ฉันเป็นเครื่องมือ... บังคับให้ฉันทำหน้าที่มิโกะ เพื่อเล่นละครหลอกลวงชาวเมือง",
  ui_story_5020_50200502_68_dialog_content = "ตลอดหลายปีที่ผ่านมา ฉันภูมิใจกับบทบาทของตัวเองในฐานะมิโกะผู้ปัดเป่าความหวาดกลัว",
  ui_story_5020_50200502_69_dialog_content = "แต่ตอนนี้ฉันไม่ได้แสดงบนเวทีแล้ว จู่ๆ ฉันก็ได้ยินเรื่องราวของตัวเองจากปากคนอื่น",
  ui_story_5020_50200502_70_dialog_content = "ฉัน... ฉันไม่รู้ว่าตัวเองเป็นใครอีกต่อไปแล้ว...",
  ui_story_5020_50200502_71_dialog_content = "ฉันควรเป็นอย่างที่คนอื่นคาดหวัง หรือควรจะทำตามที่ตัวเองต้องการ...?",
  ui_story_5020_50200601_1_dialog_content = "ทุกคน ตามมาทางนี้!",
  ui_story_5020_50200601_2_dialog_content = "หา จะออกเดินทางอีกแล้วเหรอ? คราวนี้ไปไหนล่ะ?",
  ui_story_5020_50200601_3_dialog_content = "นี่เราห่างจากซาคาอิมาเรื่อย ๆ แล้วนะ!",
  ui_story_5020_50200601_4_dialog_content = "พวกเราทุกคนจะไปจากโคฟุโจ",
  ui_story_5020_50200601_5_dialog_content = "อ้าว? ทำไมล่ะ?!",
  ui_story_5020_50200601_6_dialog_content = "ถ้าไปอยู่กลางป่าเขาแล้วเราจะขายของได้ยังไง?",
  ui_story_5020_50200601_7_dialog_content = "ภูตผีกำลังบุกเมืองตามคำสั่งของโชกุน ตอนนี้อยู่นอกเมืองจะปลอดภัยกว่า",
  ui_story_5020_50200601_8_dialog_content = "โอ๊ะ...",
  ui_story_5020_50200601_9_dialog_content = "โมโมะ... เขาบอกว่าโชกุนเป็นคนเรียกผีออกมาเหรอ?",
  ui_story_5020_50200601_10_dialog_content = "น่าจะใช่นะ อันสึ แต่ทำไมเขาต้องทำแบบนั้นล่ะ?",
  ui_story_5020_50200601_11_dialog_content = "หรือว่าโชกุนพยายามจะ... *เอื้อก* ฆ่าทุกคน...?",
  ui_story_5020_50200601_12_dialog_content = "ไม่น่าใช่นะ... ยังไงเขาก็เป็นผู้ปกครองโคฟุโจ",
  ui_story_5020_50200601_13_dialog_content = "ถ้าฆ่าชาวเมืองหมด แล้วเขาจะปกครองใครล่ะ?",
  ui_story_5020_50200601_14_dialog_content = "หรือว่าเขา... อยากจะปกครองพวกผี?",
  ui_story_5020_50200601_15_dialog_content = "ย-อย่าพูดแบบนั้นสิ! เธอทำฉันกลัวนะ!",
  ui_story_5020_50200601_16_dialog_content = "<color=#e8d9bb>เปรี้ยง!</color>",
  ui_story_5020_50200601_17_dialog_content = "?!",
  ui_story_5020_50200601_18_dialog_content = "<size=45>เฮ้ พวกแก! หยุดเดี๋ยวนี้!</size>",
  ui_story_5020_50200601_19_dialog_content = "!!!",
  ui_story_5020_50200601_20_dialog_content = "บ้าเอ๊ย...",
  ui_story_5020_50200601_21_dialog_content = "ดึกดื่นป่านนี้คิดจะไปไหนน่ะ?",
  ui_story_5020_50200601_21X1_dialog_content = "<color=#e8d9bb>หลังคาเหนือถนนของ Koufu-jou</color>",
  ui_story_5020_50200601_21X2_dialog_content = "ฉัน-มันสูงมาก! ช้าลงหน่อย!",
  ui_story_5020_50200601_21X3_dialog_content = "อีกนิดเดียวนะ ตอนนี้หลังคาเป็นทางออกจากเมืองทางเดียวที่รวดเร็วและปลอดภัย",
  ui_story_5020_50200601_22_dialog_content = "ถึงทางตันแล้ว PlayerName!",
  ui_story_5020_50200601_23_dialog_content = "เอาไงดีล่ะ?",
  ui_story_5020_50200601_24_dialog_content = "ดูเหมือนจะไม่มีทางเลือกแฮะ...",
  ui_story_5020_50200601_25_dialog_content = "เราจะกระโดดลงไปเหรอ?",
  ui_story_5020_50200601_26_dialog_content = "ใช่...",
  ui_story_5020_50200601_27_dialog_content = "ยอดเลย!",
  ui_story_5020_50200601_28_dialog_content = "นี่! อย่าโดดลงไปแบบนั้นสิ!",
  ui_story_5020_50200601_29_dialog_content = "แล้วใครจะช่วยฉันล่ะ...?",
  ui_story_5020_50200601_30_dialog_content = "เร็วเข้าเถอะ PlayerName!",
  ui_story_5020_50200601_31_dialog_content = "คุณจะไม่สามารถกระโดดได้หากผีจับคุณ!",
  ui_story_5020_50200601_32_dialog_content = "รู้แล้วน่า!",
  ui_story_5020_50200601_33_dialog_content = "ฟู่...",
  ui_story_5020_50200601_34_dialog_content = "ไปเลย!!!",
  ui_story_5020_50200601_35_dialog_content = "<anim type=Shake><size=45>อ๊าาากกก!</size></anim>",
  ui_story_5020_50200601_36_dialog_content = "<color=#e8d9bb>ตุบ!</color>",
  ui_story_5020_50200601_37_dialog_content = "ฉัน... ฉันยังไม่ตายใช่มั้ย?",
  ui_story_5020_50200601_38_dialog_content = "เป็นไปไม่ได้ที่จะหาพื้นที่ปลอดภัยเพื่อลงจอดโดยที่คุณหลับตา คุณรู้ไหม",
  ui_story_5020_50200601_39_dialog_content = "ดีนะที่ฉันรับนายได้!",
  ui_story_5020_50200601_40_dialog_content = "เธอนี่เยี่ยมที่สุดเลย ไวซ์...",
  ui_story_5020_50200601_41_dialog_content = "ขอบใจนะ แต่... ช่วยลงไปยืนบนพื้นก่อนได้มั้ย?",
  ui_story_5020_50200601_42_dialog_content = "อ-โอ๊ะ โทษที...",
  ui_story_5020_50200601_43_dialog_content = "คราวนี้...",
  ui_story_5020_50200601_44_dialog_content = "เจอกันอีกแล้วนะ คนต่างแดน",
