  ui_story_5020_50200602_111_dialog_content = "ท่านโชกุนได้พูดเรื่องนี้กับผมเอง ดังนั้นนี่เป็นเรื่องจริงแน่นอน",
  ui_story_5020_50200602_112_dialog_content = "...",
  ui_story_5020_50200602_113_dialog_content = "ฮะ... ฉันเข้าใจแล้ว",
  ui_story_5020_50200602_114_dialog_content = "ฝากไปขอบคุณท่านโชกุนด้วย ที่แสดงให้เห็นว่าฉันควรยืนข้างฝ่ายใด",
