  ui_story_5020_50200602_118_dialog_content = "ไม่จำเป็นหรอก",
  ui_story_5020_50200602_119_dialog_content = "นี่ล่ะ คือจุดที่ฉันควรอยู่",
  ui_story_5020_50200602_120_dialog_content = "...",
  ui_story_5020_50200602_121_dialog_content = "ท่านมิโกะ... ขวางพวกเราแบบนี้มีความหมายว่าอะไร ท่านคงรู้ดีใช่หรือไม่?",
  ui_story_5020_50200602_122_dialog_content = "ฉันไม่รู้",
  ui_story_5020_50200602_123_dialog_content = "ฉันแค่เลือกที่จะยืนเฉย ๆ ไม่ว่าคุณจะทำอะไร หรือจะไปที่ไหน... ก็ไม่ใช่ธุระของฉัน",
  ui_story_5020_50200602_124_dialog_content = "แต่ถ้ายืนกลางสนามรบเช่นนี้ นั่นก็เท่ากับเป็นการประกาศตนว่าเป็นศัตรูของเรา",
  ui_story_5020_50200602_125_dialog_content = "หรือจะให้พูดอีกอย่างก็คือ... เป็นศัตรูของท่านโชกุน",
  ui_story_5020_50200602_126_dialog_content = "ฉันเป็นมิโกะ ไม่เคยเห็นใครเป็นศัตรูทั้งนั้น",
  ui_story_5020_50200602_127_dialog_content = "แต่ใครบางคนอาจจะอยากเป็นศัตรูกับฉัน",
  ui_story_5020_50200602_128_dialog_content = "นี่ท่านโทษว่าเรื่องทุกอย่างเป็นความผิดของท่านโชกุนอย่างนั้นรึ?",
  ui_story_5020_50200602_129_dialog_content = "ไม่เลย. ในที่สุดฉันก็เห็นเขาว่าเขาเป็นใคร",
  ui_story_5020_50200602_130_dialog_content = "ขอขอบคุณทุกท่านที่ส่งข้อความของเขาว่า Wisps มีหน้าที่ในการเรียกผีมาที่นี่",
  ui_story_5020_50200602_131_dialog_content = "...",
  ui_story_5020_50200602_132_dialog_content = "ตอนแรกที่เห็นภูตผีในพลับพลาเมฆา ฉันก็ไม่เข้าใจ",
  ui_story_5020_50200602_133_dialog_content = "และเมื่อ Cloud Mirror ทำให้วิญญาณกลับมามีชีวิตอีกครั้ง ฉันก็ไม่เข้าใจเหมือนกัน",
  ui_story_5020_50200602_134_dialog_content = "ความขัดแย้งระหว่างคำพูดและการกระทำของท่านโชกุนทำให้ฉันสับสน... ฉันไม่เข้าใจเรื่องราวที่เกิดขึ้นเลย",
  ui_story_5020_50200602_135_dialog_content = "แต่ในที่สุด คุณกับคนของคุณก็ให้คำตอบที่ฉันต้องการ",
  ui_story_5020_50200602_136_dialog_content = "นักบวชและภูติผีต่างมองกันและกันเป็นศัตรูมาหลายชั่วอายุคน... ทว่าในสายตาของคนทั่วไปแล้ว พวกเราก็เหมือนกัน",
  ui_story_5020_50200602_137_dialog_content = "เราไม่ต่างกันเพราะเราทั้งคู่เป็นเพียงอาวุธที่จะใช้",
  ui_story_5020_50200602_138_dialog_content = "เมื่อต้องใช้กำลังอันแข็งแกร่ง เขาก็จะส่งกองทัพภูตผีไปบดขยี้ศัตรู",
  ui_story_5020_50200602_139_dialog_content = "และเมื่อต้องชนะใจผู้คน เขาก็จะส่งมิโกะออกไปกำจัดภูตผีที่ตัวเองเรียกออกมา",
  ui_story_5020_50200602_140_dialog_content = "ท่านมิโกะ ผมเชื่อว่ายังมีความจริงอีกมากที่ท่านยังไม่ทราบ",
  ui_story_5020_50200602_141_dialog_content = "บางที... และด้วยเหตุนี้ฉันจึงเลือกที่จะเชื่อเฉพาะสิ่งที่ฉันเข้าใจ",
  ui_story_5020_50200602_142_dialog_content = "ซึ่งเป็นสิ่งที่ผมได้เรียนรู้มาโดยตลอด... ผมเลือกที่จะวางใจในหน้าที่ของการเป็นนักบวช",
  ui_story_5020_50200602_143_dialog_content = "ศัตรูของฉันมีเพียงสิ่งเดียว นั่นก็คือวิญญาณร้าย",
  ui_story_5020_50200602_144_dialog_content = "...",
  ui_story_5020_50200602_145_dialog_content = "นี่คือเหตุผลที่ฉันยืนอยู่ในจุดที่ฉันอยู่ตอนนี้",
