  ui_story_5020_50200602_148_dialog_content = "...",
  ui_story_5020_50200602_149_dialog_content = "เมื่อเป็นเช่นนี้ ก็คงไม่จำเป็นต้องพูดอะไรกันอีกแล้ว",
