  ui_story_5020_50200602_151_dialog_content = "<color=#e8d9bb>กริ๊ง...</color>",
  ui_story_5020_50200602_152_dialog_content = "\"ข้าขอกล่าวบทสวดแห่งหยินหยาง เพื่อชี้นำดวงวิญญาณของเจ้ากลับสู่สถานที่อันสมควร\"",
  ui_story_5020_50200701_1_dialog_content = "(ขณะที่เราเฝ้าดูผีซามูไรเข้ามาใกล้ ร่างกายของเราก็ชาจากแรงกดดันมหาศาล)",
  ui_story_5020_50200701_2_dialog_content = "(ราวกับคลื่นยักษ์เตรียมถาโถมซัดสาด)",
  ui_story_5020_50200701_3_dialog_content = "(แต่ที่นั่น กลางถนน รินเนะยืนอยู่อย่างโดดเดี่ยวและไม่สะทกสะท้านกับคลื่นที่กำลังมา)",
  ui_story_5020_50200701_4_dialog_content = "(ดวงตาทั้งสองจับจ้องในห้วงลึกของอเวจี โดยมีโลกของคนเป็นอยู่เบื้องหลัง)",
  ui_story_5020_50200701_5_dialog_content = "โอ๊ะ...?",
  ui_story_5020_50200701_6_dialog_content = "ฉันนึกว่ากองพลโชคุยูจะไม่อยากต่อสู้เคียงข้างมิโกะซะอีก?",
  ui_story_5020_50200701_7_dialog_content = "...",
  ui_story_5020_50200701_8_dialog_content = "ถ้าให้เธอปกป้องเรา นั่นจะเป็นการเสื่อมเสียเกียรติยิ่งกว่าเดิม",
  ui_story_5020_50200701_9_dialog_content = "หึหึ น่าเสียดายจริง",
  ui_story_5020_50200701_10_dialog_content = "ถ้าพวกคุณต้องยุ่งกับการต่อสู้ แล้วใครจะมาชม... \"การแสดง\" ของฉันล่ะ?",
  ui_story_5020_50200701_11_dialog_content = "\"การแสดง\" งั้นเรอะ? ฟังแล้วแสลงหูจังแฮะ...",
  ui_story_5020_50200701_12_dialog_content = "คุณเป็นคนสอนคำนั้นกับฉันเองนี่",
  ui_story_5020_50200701_13_dialog_content = "เจ้าคิดเจ้าแค้นจังเลยนะ... หรือคำพูดของฉันมันจี้ใจดำกันแน่",
  ui_story_5020_50200701_14_dialog_content = "อืมม ก็ไม่ผิดนักหรอก",
  ui_story_5020_50200701_15_dialog_content = "การตั้งตัวเป็นศัตรูกับมิโกะ ก็แสดงว่าคุณเข้าใจอะไร ๆ ดีกว่าฉัน",
  ui_story_5020_50200701_16_dialog_content = "ถ้าเธอรู้ทุกอย่างเหมือนที่ฉันรู้... ฉันมั่นใจว่าเธอก็จะต้องเกลียดตัวเองเหมือนกัน",
  ui_story_5020_50200701_17_dialog_content = "อา... อย่าเพิ่งด่วนตัดสิน",
  ui_story_5020_50200701_18_dialog_content = "ถึง \"การแสดง\" จะเป็นคำพูดที่ใจร้ายไปหน่อย แต่ฉันก็ไม่รังเกียจมันหรอกนะ",
  ui_story_5020_50200701_19_dialog_content = "แสดงว่าเธอยังอยากจะเป็นหุ่นเชิดต่อไปงั้นรึ?",
  ui_story_5020_50200701_20_dialog_content = "สิ่งที่เกี่ยวข้องกับคุณและคนของคุณคือผู้ที่ดึงสายของหุ่นเชิดเท่านั้น",
  ui_story_5020_50200701_21_dialog_content = "ส่วนตัวฉัน ต้องการแค่จะมอบการแสดงอันน่าประทับใจแก่ผู้ชมเท่านั้น",
  ui_story_5020_50200701_22_dialog_content = "ถ้าพูดแบบนั้น หุ่นเชิดก่อนหน้าเธอก็ไม่เคยมีใครทำสำเร็จสักคน",
  ui_story_5020_50200701_23_dialog_content = "งั้นรึ? ถ้าอย่างนั้น คิดว่าคราวนี้ฉันจะทำได้รึเปล่าล่ะ?",
  ui_story_5020_50200701_24_dialog_content = "...",
  ui_story_5020_50200701_25_dialog_content = "นี่เป็นเหตุผลที่พวกคุณหมกมุ่นกับการลอบสังหารมิโกะสินะ?",
  ui_story_5020_50200701_26_dialog_content = "อาเมะโมริสร้างปัญหาให้ฉันน่าดูเลย รู้มั้ย?",
  ui_story_5020_50200701_27_dialog_content = "อาเมะ...",
  ui_story_5020_50200701_28_dialog_content = "ต้องเรียกว่าท่านอาเมะโมริสิ เข้าใจมั้ย? รู้จักมารยาทหน่อย!",
  ui_story_5020_50200701_29_dialog_content = "โอ๊ะ?",
  ui_story_5020_50200701_30_dialog_content = "แต่อาเมะโมริเองก็ล้มเหลวทุกครั้ง... ฉันนึกว่าท้ายที่สุดแล้วเธอยอมแพ้เพื่อไม่ให้ตัวเองต้องอับอายขายหน้า",
