  ui_story_5020_50200701_36_dialog_content = "แม่ทัพของพวกคุณมีฉายาว่าดาบแห่งยมโลกใช่ไหม?",
  ui_story_5020_50200701_37_dialog_content = "ทำไม คุณเคยเห็นเธอไหม?",
  ui_story_5020_50200701_38_dialog_content = "เคยสิ เราต่อสู้กันด้วย",
  ui_story_5020_50200701_39_dialog_content = "ในฐานะคนที่สามารถต่อสู้บนพื้นราบกับนายพลได้... เธอทรงพลังอย่างน่าสะพรึงกลัว",
  ui_story_5020_50200701_40_dialog_content = "และอาเมะโมริก็ต้องรับหน้าที่แทนเธอเป็นเวลานานหลายปี... คงเป็นภาระที่หนักอึ้งเหลือเกิน",
  ui_story_5020_50200701_41_dialog_content = "ท่านอาเมะโมริมีหลายสิ่งเหมือนท่านแม่ทัพ และเธอก็ปฏิบัติหน้าที่ได้อย่างน่าชื่นชม",
  ui_story_5020_50200701_42_dialog_content = "ในบางเรื่อง... เธอก็ทำได้ดีกว่าท่านแม่ทัพด้วยซ้ำ",
