  ui_story_5020_50200701_44_dialog_content = "แต่ถ้าเป็นทักษะการสังหารมิโกะล่ะก็ ยังต้องปรับปรุงอีกเยอะนะ",
  ui_story_5020_50200701_45_dialog_content = "ว่าแต่แม่ทัพของคุณล่ะ เก่งเรื่องนี้รึเปล่า?",
  ui_story_5020_50200701_46_dialog_content = "...",
  ui_story_5020_50200701_47_dialog_content = "ฉันว่าเธอรู้คำตอบนั่นดีอยู่แล้วนะ",
  ui_story_5020_50200701_48_dialog_content = "คิดให้ดีสิ ว่าทำไมเธอถึงได้มาเป็นมิโกะคนปัจจุบัน",
