  ui_story_5020_50200702_20_dialog_content = "จะเกิดอะไรขึ้นถ้า Wisp บังคุณจากด้านหลัง? คุณสามารถหลบหนีได้หรือไม่?",
  ui_story_5020_50200702_21_dialog_content = "เอ๊ะ?",
  ui_story_5020_50200702_22_dialog_content = "ตั้งใจฟัง. ตอนนี้คุณเป็นคนนอกสองคนต้องออกไปจากที่นี่และพานักบวชหญิงไปด้วย",
  ui_story_5020_50200702_23_dialog_content = "เราจะคุ้มกันพวกนายให้เอง แต่คงจะต้านไว้ไม่ได้นานหรอกนะ",
  ui_story_5020_50200702_24_dialog_content = "นายจะต้องใช้พลังประหลาดนั่นให้คุ้มค่าทุกวินาทีเพื่อหาโอกาสหนีให้ได้",
  ui_story_5020_50200702_25_dialog_content = "เข้าใจมั้ย?",
  ui_story_5020_50200702_26_dialog_content = "เข้าใจครับ แต่ว่า...",
  ui_story_5020_50200702_27_dialog_content = "ทำไมถึงทำแบบนี้ล่ะ?",
  ui_story_5020_50200702_28_dialog_content = "...",
  ui_story_5020_50200702_29_dialog_content = "นักบวชหญิง คนจำนวนมากควรได้เห็นการแสดงนี้ของคุณ",
  ui_story_5020_50200702_30_dialog_content = "...",
  ui_story_5020_50200702_31_dialog_content = "ตอนนี้กองพลโชคุยูไม่มีกำลังพอจะรับมือกับโชกุนได้อยู่แล้ว",
  ui_story_5020_50200702_32_dialog_content = "แต่กับคุณสามคน... ยังพอมีหวัง",
  ui_story_5020_50200702_33_dialog_content = "ในเมื่อพวกเราสู้ศึกที่ไม่มีทางชนะมาเนิ่นนานขนาดนี้ ฉันก็ยินดีเสี่ยง แทนที่จะต้องรอให้ถึงจุดจบ",
  ui_story_5020_50200702_34_dialog_content = "ตรึงแนวรบให้ดี ทหาร! อย่าปรานีพวกมันเด็ดขาด!",
  ui_story_5020_50200702_35_dialog_content = "พอพวกเราหนีไปได้แล้ว แล้วพวกคุณล่ะ?",
  ui_story_5020_50200702_36_dialog_content = "<size=45>รีบไปได้แล้วน่า ไอ้หนู!</size>",
  ui_story_5020_50200702_37_dialog_content = "...",
