  ui_story_5020_50200702_39_dialog_content = "พวกเขาเลือกแล้ว",
  ui_story_5020_50200702_40_dialog_content = "นายติดหนี้ฉันแล้วนะ ไอ้หนู! อย่าลืมซะล่ะ!",
