  ui_story_5020_50200702_42_dialog_content = "ว้าว!",
  ui_story_5020_50200702_43_dialog_content = "กลองใบใหญ่จัง!",
  ui_story_5020_50200702_44_dialog_content = "ใหญ่สุด ๆ ไปเลย!",
  ui_story_5020_50200702_45_dialog_content = "กลองนั่นมีไว้ทำไมเหรอครับ พ่อ?",
  ui_story_5020_50200702_46_dialog_content = "เอาไว้ตีส่งสัญญาณเริ่มต้นเทศกาลคาสึกะน่ะ",
  ui_story_5020_50200702_47_dialog_content = "กลองนั่นเสียงดังพอที่ทุกคนในโคฟุโจจะได้ยิน ทุกคนจะได้รู้ว่าเทศกาลคาสึกะเริ่มขึ้นแล้ว",
  ui_story_5020_50200702_48_dialog_content = "โอ้โห!",
  ui_story_5020_50200702_49_dialog_content = "แล้วทำไมถึงมาตั้งอยู่ตรงนี้ล่ะ? คนตีกลองไปไหนซะแล้ว?",
