  ui_story_5020_50200801_14_dialog_content = "ไม่ใช่แค่ฉันคนเดียว... ทุกคนในกองพลโชคุยูก็เช่นกัน",
  ui_story_5020_50200801_15_dialog_content = "กี่ปีแล้ว...?",
  ui_story_5020_50200801_16_dialog_content = "10 ปีค่ะ",
  ui_story_5020_50200801_17_dialog_content = "10 ปีเชียวเหรอ?! ฮ่าฮ่าฮ่า! มันก็นานจริง ๆ ล่ะนะ?",
  ui_story_5020_50200801_18_dialog_content = "ฉันจำได้ว่าเธอเป็นอย่างไรในตอนนั้น... สั้นกว่าดาบของฉัน ฉันกังวลอยู่เสมอว่าสายลมจะพัดพาคุณไป",
