  ui_story_5020_50200801_21_dialog_content = "น่าเสียดาย ที่ดูเหมือนว่าสติปัญญาของเธอจะไม่ได้โตตามไปด้วย",
  ui_story_5020_50200801_22_dialog_content = "\"แบกรับภาระของฉัน\"... เธอเข้าใจความหมายของมันจริง ๆ รึเปล่า?",
  ui_story_5020_50200801_23_dialog_content = "เพื่อ... เพื่อสานต่อสิ่งที่ท่านต้องการทำให้สำเร็จมาตลอด",
  ui_story_5020_50200801_24_dialog_content = "นั่นก็คือการคืนโคฟุโจให้กับผู้ปกครองโดยชอบธรรม",
  ui_story_5020_50200801_25_dialog_content = "ฮ่าฮ่าฮ่าฮ่า! เข้าใจละ!",
  ui_story_5020_50200801_26_dialog_content = "นี่เป็นเหตุผลที่เธอบุกมาช่วยฉันเหรอ?",
  ui_story_5020_50200801_27_dialog_content = "เธออยากให้ฉันจบเรื่องทุกอย่างนี่ ใช่ไหม?",
