  ui_story_5020_50200801_121_dialog_content = "แต่ฉันมักจะหัวเราะเยาะเธอโดยบอกว่านักบวชหญิงเป็นเพียงเครื่องมือของคนทั่วไป... วิธีเดียวที่จะนำความสงบสุขมาสู่ Cloud Island คือการใช้ใบมีด",
  ui_story_5020_50200801_122_dialog_content = "ท้ายที่สุดก็ไม่มีใครยอมฟังใคร พวกเราจึงเลือกเดินในเส้นทางที่ตนเองเชื่อมั่น",
  ui_story_5020_50200801_123_dialog_content = "เธอเดินทางไปยังเกาะหลักเพื่อรับการฝึกฝนอย่างเป็นทางการ ส่วนฉัน... ออกเดินทางร่อนเร่ไปทั่ว สังหารภูตผีมากมายเพื่อฝึกปรือฝีมือ",
  ui_story_5020_50200801_124_dialog_content = "เวลาผ่านไปไม่กี่ปี เธอก็ขึ้นมาเป็นมิโกะของโชกุน ส่วนฉันก็ได้รับสมญานามดาบแห่งยมโลก",
  ui_story_5020_50200801_125_dialog_content = "...",
  ui_story_5020_50200801_126_dialog_content = "ครั้งต่อไปที่เราเจอกัน เธอไม่เสียเวลาไปกับการหวนคิดถึงอดีตอีกแล้ว ทั้งหมดที่เธอพูดคือเธอต้องการดูว่าใครสามารถสังหารผีได้ดีกว่ากัน",
  ui_story_5020_50200801_127_dialog_content = "ฉันแทบจะกลั้นหัวเราะไว้ไม่อยู่และตอบรับคำท้าของเธอด้วยความยินดี",
  ui_story_5020_50200801_128_dialog_content = "สิ่งสุดท้ายที่ฉันคาดหวังคือการได้เห็นเธอชักดาบออกมาอย่างมั่นใจ",
  ui_story_5020_50200801_129_dialog_content = "นั่นเป็นดาบที่งดงามที่สุดที่ฉันเคยเห็น เปล่งพลังโชติช่วงราวกับดวงตะวัน... เหมือนกับว่ามันถูกสร้างขึ้นเพื่อฟาดฟันปีศาจและความมืดมิด",
  ui_story_5020_50200801_130_dialog_content = "แน่นอนว่าฉันแพ้หมดรูป หึหึ... ฉันยังจำได้ว่าสึกิภูมิใจกับชัยชนะครั้งนั้นสุด ๆ เธอเต้นรอบ ๆ ฉันพร้อมพูดว่า—",
  ui_story_5020_50200801_131_dialog_content = "\"ฉันบอกคุณแล้ว นักบวชหญิงสามารถนำความสงบสุขมาสู่เกาะเมฆาได้!\"",
