  ui_story_5020_50200801_135_dialog_content = "Slice of Heaven ดาบสังหารภูตผี... แม้แต่เด็กอายุสามขวบก็สามารถฟันวิญญาณส่วนใหญ่ได้ด้วยดาบเล่มนั้น ไม่ต้องพูดถึงน้องสาวของฉัน",
