  ui_story_5020_50200801_224_dialog_content = "อาจารย์คะ... อาจารย์เคยเสียใจที่ได้สังหารคุณสึกิไหม?",
  ui_story_5020_50200801_225_dialog_content = "แน่นอน ฉันไม่เสียใจเรื่องนั้นแม้แต่น้อย",
  ui_story_5020_50200801_226_dialog_content = "แล้วทำไมถึงถามเรื่องงานศพล่ะคะ?",
  ui_story_5020_50200801_227_dialog_content = "...",
  ui_story_5020_50200801_228_dialog_content = "ฉันไม่เสียใจที่ได้สังหารเธอ แต่...",
  ui_story_5020_50200801_229_dialog_content = "ยังไงเธอก็เป็นพี่สาวของฉัน ฉันควรเป็นคนที่ฝังร่างเธอ",
  ui_story_5020_50200801_230_dialog_content = "ค่ะ...",
  ui_story_5020_50200801_231_dialog_content = "และยังมีอีกสิ่งหนึ่ง",
  ui_story_5020_50200801_232_dialog_content = "Slice of Heaven เป็นของเธอ ถ้าให้เดาก็น่าจะถูกฝังอยู่กับเธอ",
  ui_story_5020_50200801_233_dialog_content = "ยังไงก็ตาม มันถูกสร้างขึ้นเพื่อสังหารปีศาจ โชกุนคงไม่อยากได้ของแบบนั้นอยู่แล้ว",
  ui_story_5020_50200801_234_dialog_content = "คุณต้องการค้นหา Slice of Heaven, Master?",
  ui_story_5020_50200801_235_dialog_content = "ถูกต้อง",
  ui_story_5020_50200801_236_dialog_content = "สึกิคงนอนตายตาไม่หลับ ถ้าเธอรู้ว่าดาบเล่มโปรดของเธอถูกทิ้งให้ขึ้นสนิมในกองดิน",
  ui_story_5020_50200801_237_dialog_content = "<color=#e8d9bb>ตุบ ตุบ</color>",
  ui_story_5020_50200801_238_dialog_content = "ฟู่! ไม่ได้ปีนขึ้นมาบนนี้นานเท่าไหร่แล้วนะ!",
  ui_story_5020_50200801_239_dialog_content = "เอาล่ะ ศิษย์ของฉัน คลายเชือกแล้วส่งมาให้ฉันขวดนึงสิ",
  ui_story_5020_50200801_240_dialog_content = "มาดูกันว่าผ่านมาสิบปีแล้ว เพื่อนของฉันจะทำเหล้าเก่งขึ้นมั้ย",
  ui_story_5020_50200801_241_dialog_content = "ค่ะ...",
  ui_story_5020_50200801_242_dialog_content = "ว่าแต่... เธอโตพอที่จะดื่มเหล้าหรือยังน่ะ?",
  ui_story_5020_50200801_243_dialog_content = "ฉัน... ฉันคออ่อนมากเลย",
  ui_story_5020_50200801_244_dialog_content = "น่าเบื่อจริง ๆ",
  ui_story_5020_50200801_245_dialog_content = "เอาล่ะ ช่างเถอะ เอามาให้ฉันขวดนึง แล้วก็<color=#FFB400>ฟาด</color>ขวดที่เหลือให้แตก",
  ui_story_5020_50200801_246_dialog_content = "ฟาดให้แตก? ทำไมล่ะคะ...?",
  ui_story_5020_50200801_247_dialog_content = "นี่เธอไม่เชื่อใจฉันหรือไง? ฉันบอกให้ฟาดขวดก็รีบ ๆ ทำไป! เข้าใจมั้ย?",
  ui_story_5020_50200801_248_dialog_content = "ได้ค่ะ",
  ui_story_5020_50200801_249_dialog_content = "<color=#e8d9bb>เพล้ง!</color>",
  ui_story_5020_50200801_250_dialog_content = "<color=#e8d9bb>เพล้ง!</color>",
  ui_story_5020_50200801_251_dialog_content = "<color=#e8d9bb>เพล้ง!!</color>",
  ui_story_5020_50200801_252_dialog_content = "ฮ่าฮ่าฮ่าฮ่าฮ่า! แบบนั้นล่ะ!",
  ui_story_5020_50200801_253_dialog_content = "<anim type=Shake>อึ้ก อึ้ก...</anim>",
  ui_story_5020_50200801_254_dialog_content = "ฮ่า! ของดีเลยนี่นา!",
  ui_story_5020_50200801_255_dialog_content = "<color=#e8d9bb>ตุบ ตุบ ตุบ</color>",
  ui_story_5020_50200801_256_dialog_content = "กรุณาพยายามอย่าล้มลงอาจารย์",
  ui_story_5020_50200801_257_dialog_content = "ฮ่า! คิดว่ากำลังพูดอยู่กับใครน่ะ หา?",
  ui_story_5020_50200801_258_dialog_content = "มองลงไปข้างล่างสิ อาเมะโมริ",
  ui_story_5020_50200801_259_dialog_content = "เห็นผู้ชายที่เดินอยู่ตรงนั้นมั้ย? บอกฉันทีสิว่าเขาเป็นใคร?",
  ui_story_5020_50200801_260_dialog_content = "...",
  ui_story_5020_50200801_261_dialog_content = "นั่นฟูจิคุโมะนี่",
  ui_story_5020_50200801_262_dialog_content = "เขากำลังทำอะไรอยู่?",
  ui_story_5020_50200801_263_dialog_content = "ฉันจะบอกคุณบางอย่าง ศัตรูเข้าใจกันและกันดีที่สุด",
  ui_story_5020_50200801_264_dialog_content = "แม้จากในระยะนี้ บนหลังคาของอาคารที่ต่างไปจากเดิม... ฉันก็ยังเข้าใจว่าตอนนี้เจ้านั่นคิดอะไรอยู่",
  ui_story_5020_50200801_265_dialog_content = "ตอนนี้เขาต้องกำลังคิดว่าเขากำลังก้าวไปสู่ความสงบ",
  ui_story_5020_50200801_266_dialog_content = "ทำไมล่ะคะ?",
  ui_story_5020_50200801_267_dialog_content = "เพราะนั่นก็เป็นสิ่งที่ฉันคิดอยู่เหมือนกัน",
  ui_story_5020_50200801_268_dialog_content = "!!!",
  ui_story_5020_50200801_269_dialog_content = "แต่อาจารย์...",
  ui_story_5020_50200801_270_dialog_content = "มาเถอะ! ดื่มคนเดียวมันไม่สนุกหรอกนะ!",
  ui_story_5020_50200801_271_dialog_content = "ถ้าลูกศิษย์ของฉันไม่ดื่มกับฉัน ฉันคงต้องขอ Koufu-jou ทั้งหมดแทน!",
  ui_story_5020_50200901_1_dialog_content = "ท่านโชกุน! กองกำลังหลักของโชคุยูถูกจับกุมแล้ว ขณะนี้เรากำลังพาตัวมันไปที่ปราสาท",
  ui_story_5020_50200901_2_dialog_content = "ดี",
  ui_story_5020_50200901_3_dialog_content = "วันนี้ธงกบฏจะถูกเผาเป็นเถ้าถ่าน",
  ui_story_5020_50200901_4_dialog_content = "แจ้งชาวเมืองทุกคน! บอกให้พวกเขามาที่ปราสาทเพื่อเป็นประจักษ์พยานการพิพากษาคนทรยศพวกนี้!",
  ui_story_5020_50200901_5_dialog_content = "หลังจากค่ำคืนอันน่าหวาดกลัว จะต้องมีผู้รับผิดชอบสำหรับความวุ่นวายที่คุกคามเมืองอันงดงามของเรา",
  ui_story_5020_50200901_6_dialog_content = "เรายังมีเทศกาล Kasuga ในตอนเช้า",
  ui_story_5020_50200901_7_dialog_content = "ขอรับ",
  ui_story_5020_50200901_8_dialog_content = "<color=#e8d9bb>กะทึก... กะทึก...</color>",
  ui_story_5020_50200901_9_dialog_content = "เฮ้! เราจะไปที่ที่คนน้อยลงจริงหรือ?",
  ui_story_5020_50200901_10_dialog_content = "ทำไมข้างนอกมันดูวุ่นวายยังไงไม่รู้",
  ui_story_5020_50200901_11_dialog_content = "ก็ช่วยไม่ได้ล่ะนะ PlayerName",
  ui_story_5020_50200901_12_dialog_content = "การผลักกลองมหึมานั้นจะทำให้เห็นได้ชัดเจนเกินไป ทางออกที่ดีที่สุดของเราคือซ่อนตัวในฝูงชนและติดตามพวกเขา",
  ui_story_5020_50200901_13_dialog_content = "เอาล่ะ ถ้างั้น... ตอนนี้เราอยู่ที่ไหนแล้ว?",
  ui_story_5020_50200901_14_dialog_content = "เราน่าจะ...",
  ui_story_5020_50200901_15_dialog_content = "ด้านนอกปราสาท",
  ui_story_5020_50200901_16_dialog_content = "หา?! นี่เธอจะพาเราไปโดนเชือดหรือไง?!",
  ui_story_5020_50200901_17_dialog_content = "ไม่ต้องห่วง เดี๋ยวเราคิดแผนให้น่า!",
  ui_story_5020_50200901_18_dialog_content = "หากเลวร้ายที่สุด คุณจะต้องซ่อนตัวจนกว่าจะสิ้นสุดเทศกาล Kasuga...",
  ui_story_5020_50200901_19_dialog_content = "คุณกำลังพยายามจะฆ่าพวกเราจริงๆ ใช่ไหม!",
  ui_story_5020_50200901_20_dialog_content = "<size=45>เคลียร์เส้นทาง!</size>",
  ui_story_5020_50200901_21_dialog_content = "<size=45>อย่าขวาง!</size>",
  ui_story_5020_50200901_22_dialog_content = "คราวนี้อะไรอีกล่ะ?",
  ui_story_5020_50200901_23_dialog_content = "ซามูไรกำลังนำคนกลุ่มใหญ่มาทางนี้!",
  ui_story_5020_50200901_24_dialog_content = "เดี๋ยวนะ นั่นมัน...?",
  ui_story_5020_50200901_25_dialog_content = "ใช่แล้ว! พวกโชคุยูนี่นา!",
  ui_story_5020_50200901_26_dialog_content = "โชคุยู?!",
  ui_story_5020_50200901_27_dialog_content = "พวกเขาถูกจับเหรอ?",
  ui_story_5020_50200901_28_dialog_content = "น่าจะเป็นอย่างนั้นแหละ...",
  ui_story_5020_50200901_29_dialog_content = "พวกเขากำลังมุ่งหน้าไปยังปราสาทเช่นกัน",
  ui_story_5020_50200901_30_dialog_content = "ปราสาทหลัก... โชกุนจะทำอะไรพวกเขามั้ยนะ?",
  ui_story_5020_50200901_31_dialog_content = "เขาจะใช้พวกเขาเป็นแพะรับบาป ใครบางคนสำหรับประชาชนที่จะชี้นำความโกรธและความกลัวของพวกเขาที่",
  ui_story_5020_50200901_32_dialog_content = "แต่นี่ไม่ใช่ความผิดของพวกเขาเลยนะ!",
  ui_story_5020_50200901_33_dialog_content = "ชาวเมืองจะเชื่อเรื่องนี้จริง ๆ น่ะเหรอ?",
  ui_story_5020_50200901_34_dialog_content = "ท่านโชกุนควบคุมภูตผีได้อย่างสมบูรณ์ สามารถเรียกและกำจัดพวกมันได้ตามต้องการ",
  ui_story_5020_50200901_35_dialog_content = "ตอนนี้ Wisp ถูกจับแล้ว เขาสามารถหยุดการโจมตีได้อย่างง่ายดายและทำให้ผู้คนเชื่อว่ากลุ่มกบฏต้องรับผิดชอบ",
  ui_story_5020_50200901_36_dialog_content = "ชาวเมืองก็มีแต่ต้องเชื่อเขา",
  ui_story_5020_50200901_37_dialog_content = "แต่ถ้าเกิดเรื่องแบบนั้น...",
  ui_story_5020_50200901_38_dialog_content = "ถ้าเกิดเรื่องแบบนั้น...",
  ui_story_5020_50200901_39_dialog_content = "เอ๊ะ?",
  ui_story_5020_50200901_40_dialog_content = "ก็จะไม่มีภูตผีในโคฟุโจอีกต่อไป...",
  ui_story_5020_50200901_41_dialog_content = "นั่นก็... เป็นเรื่องที่ดีไม่ใช่เหรอ?",
  ui_story_5020_50200901_42_dialog_content = "เธอก็มีเหตุผลนะ...",
  ui_story_5020_50200901_43_dialog_content = "นี่คือกลยุทธ์ของผู้ปกครองที่เย็นชาและไร้ความปรานี",
  ui_story_5020_50200901_44_dialog_content = "เขาเสียสละและทรยศผู้อื่นโดยไม่ลังเล",
  ui_story_5020_50200901_45_dialog_content = "แต่ท้ายที่สุด... สิ่งต่าง ๆ ก็จะคลี่คลายไปในทางที่ดีขึ้น อย่างน้อยก็แค่เปลือกนอก",
  ui_story_5020_50200901_46_dialog_content = "...",
  ui_story_5020_50200901_47_dialog_content = "มันก็ดีขึ้นแค่เปลือกนอกใช่ไหมล่ะ?",
  ui_story_5020_50200901_48_dialog_content = "ชาวเกาะเมฆเชื่อในการมีอยู่ของวิญญาณอย่างสุดหัวใจ",
  ui_story_5020_50200901_49_dialog_content = "หากสิ่งต่างๆ เป็นไปตามที่ฉันคาดการณ์ไว้ ทุกคนก็จะใช้ชีวิตในโลกลวงตาของคนทั่วไปอย่างมีความสุขและไร้กังวล",
  ui_story_5020_50200901_50_dialog_content = "แต่วิญญาณที่อาศัยอยู่ในความบาปที่ไม่รู้ความจริงอันเลวร้ายนั้นก็ไม่ต่างอะไรจากความตาย",
  ui_story_5020_50200901_51_dialog_content = "ฉันเชื่อว่าถ้ามีคนรู้ความจริง เขาก็ย่อมไม่นิ่งดูดายและยอมรับในสิ่งที่เกิดขึ้น",
  ui_story_5020_50200901_52_dialog_content = "ถูกตัอง! ทั้งเมืองจะอยู่ภายใต้ภาพลวงตาของการโกหกได้อย่างไร?",
  ui_story_5020_50200901_53_dialog_content = "ทุกคนควรได้รู้ความจริง!",
  ui_story_5020_50200901_54_dialog_content = "...",
  ui_story_5020_50200901_55_dialog_content = "ทั้งสองคนพูดถูก",
  ui_story_5020_50200901_56_dialog_content = "สันติภาพที่สร้างขึ้นบนภูเขาแห่งการโกหกนั้นไม่ใช่สันติภาพเลย",
  ui_story_5020_50200901_57_dialog_content = "เราจะต้องเปิดโปงความจริงให้ทุกคนได้รู้",
  ui_story_5020_50200901_58_dialog_content = "<color=#e8d9bb>ตุบ... ตุบ...</color>",
  ui_story_5020_50200901_59_dialog_content = "อันสึ โมโมะ... เธอคิดว่าจะตามพวกโชคุยูที่ถูกจับไปทันมั้ย?",
  ui_story_5020_50200901_60_dialog_content = "ตามไปเนี่ยนะ?",
  ui_story_5020_50200901_61_dialog_content = "แบบนั้นเราก็จะหมดทางหนีนะ",
  ui_story_5020_50200901_62_dialog_content = "เราจะไม่หนี ไม่อีกต่อไปแล้ว",
  ui_story_5020_50200901_63_dialog_content = "ฉันไม่อยากพลาดเทศกาลคาสึกะหรอกนะ!",
  ui_story_5020_50200901_64_dialog_content = "ได้ยินว่าจะมีการพิพากษาโทษพวกกบฏล่ะ... จริงรึเปล่า?",
  ui_story_5020_50200901_65_dialog_content = "จริงสิ! ท่านโชกุนบอกเอง!",
  ui_story_5020_50200901_66_dialog_content = "ในที่สุด พวกคนทรยศที่เรียกผีมาก่อความวุ่นวายก็จะโดนลงโทษเนอะ!",
  ui_story_5020_50200901_67_dialog_content = "ดูนั่นสิ! ทหารพาตัวพวกมันไปที่จัตุรัสแล้ว!",
  ui_story_5020_50200901_68_dialog_content = "เดี๋ยวนะ พวกนั้นใช่กบฏจริง ๆ เหรอ? ฉันรู้จักอยู่หลายคนเลย!",
  ui_story_5020_50200901_69_dialog_content = "ใครจะรู้ล่ะ พวกเขาอาจโดนใส่ร้ายให้เป็นแพะรับบาปก็ได้...",
  ui_story_5020_50200901_70_dialog_content = "ฮึ่ม! นายพลรู้วิธีที่จะรักษาตำแหน่งของเขา",
  ui_story_5020_50200901_71_dialog_content = "เอาเถอะ คนที่ก่อเรื่องพวกนี้ จะเป็นใครก็แล้วแต่ พวกมันควรได้รับโทษอย่างสาสม...",
  ui_story_5020_50200901_72_dialog_content = "<color=#e8d9bb>โครม...!</color>",
  ui_story_5020_50200901_73_dialog_content = "ท่านโชกุน!",
  ui_story_5020_50200901_74_dialog_content = "เราจับตัวกบฏโชคุยูทุกคนสำเร็จแล้ว!",
  ui_story_5020_50200901_75_dialog_content = "เราขอให้คุณตัดสินพวกเขาสำหรับอาชญากรรมที่ชั่วร้ายของพวกเขาด้วยความถ่อมตน!",
  ui_story_5020_50200901_76_dialog_content = "ข้าเดินทางมาที่โคฟุโจหลายสิบปีแล้ว",
  ui_story_5020_50200901_77_dialog_content = "ฉันเริ่มเบื่อหน่ายกับการต่อสู้อย่างต่อเนื่องและไม่น่าดูที่อยู่รอบตัวฉันตั้งแต่นั้นเป็นต้นมา",
  ui_story_5020_50200901_78_dialog_content = "ทุกอย่างจบลงในวันนี้ ที่นี่. ตอนนี้.",
  ui_story_5020_50200901_79_dialog_content = "ฉันมองเห็นรุ่งอรุณแห่งสันติภาพใกล้เข้ามา...",
  ui_story_5020_50200901_80_dialog_content = "สันติสุข...",
  ui_story_5020_50200901_81_dialog_content = "เมื่อสงครามเข้าคุกคามชาวเมืองโคฟุโจ ข้าก็คือผู้ที่ยุติศึกสงครามนั้น",
  ui_story_5020_50200901_82_dialog_content = "เมื่อภูตผีเข้าคุกคามวิถีชีวิตของผู้คน ข้าก็เริ่มฝึกฝนมิโกะเพื่อสยบผีร้ายไม่ให้ออกอาละวาด",
  ui_story_5020_50200901_83_dialog_content = "ภายใต้การปกครองของข้า ชาวโคฟุโจทุกคนล้วนได้พบกับความสงบสุขสันติอย่างที่ไม่เคยเป็นมาก่อน",
  ui_story_5020_50200901_84_dialog_content = "แต่ถึงกระนั้นก็ยังมีคนที่ไม่รู้จักพอ",
  ui_story_5020_50200901_85_dialog_content = "พวกมันเหยียบย่ำความเป็นระเบียบเรียบร้อยที่ข้าปกปักรักษา และเรียกร้องเอาประโยชน์อย่างไร้ยางอาย!",
  ui_story_5020_50200901_86_dialog_content = "ตอนนี้พวกเขาคุกเข่าต่อหน้าพวกเราทุกคน",
  ui_story_5020_50200901_87_dialog_content = "...",
  ui_story_5020_50200901_88_dialog_content = "Wisp กบฏ คุณตระหนักถึงบาปของคุณหรือไม่?",
  ui_story_5020_50200901_89_dialog_content = "บาปงั้นเรอะ?",
  ui_story_5020_50200901_90_dialog_content = "จริงๆแล้วฉันไม่มีความคิด",
  ui_story_5020_50200901_91_dialog_content = "คุณฟังดูเหมือนคุณรู้ ทำไมฉันไม่ให้เกียรติคุณที่บอกเรา",
  ui_story_5020_50200901_92_dialog_content = "ย่อมได้ ข้าจะเล่าให้พวกเจ้าฟัง",
  ui_story_5020_50200901_93_dialog_content = "คุณสมรู้ร่วมคิดกับภูติผีปีศาจที่ก่อกวนความสงบเรียบร้อยของ Koufu-jou",
  ui_story_5020_50200901_94_dialog_content = "และโทษของความผิดนั้น ก็คือการประหาร!",
  ui_story_5020_50200901_95_dialog_content = "เหอะ",
  ui_story_5020_50200901_96_dialog_content = "ฟูจิคุโมะ คุณแก่...",
  ui_story_5020_50200901_97_dialog_content = "(เอ่อ ขอโทษนะ ฉันเกลียดการขัดจังหวะคำพูดของคุณ)",
  ui_story_5020_50200901_98_dialog_content = "(แต่ช่วยอย่าเพิ่งยั่วโมโหโชกุน แล้วถ่วงเวลาให้เราหน่อยได้มั้ย?)",
  ui_story_5020_50200901_99_dialog_content = "(จะเป็นการยากที่จะช่วยคุณหากคุณถูกประหารชีวิตในทันที)",
  ui_story_5020_50200901_100_dialog_content = "...",
  ui_story_5020_50200901_101_dialog_content = "(Anzu และ Momo จะแก้มัดคุณในภายหลัง มันจะเป็นโอกาสเดียวของเรา)",
  ui_story_5020_50200901_102_dialog_content = "(คุณต้องปราบซามูไรทั้งหมดในคราวเดียว ไม่เช่นนั้นพวกเราก็โดนหลอก)",
  ui_story_5020_50200901_103_dialog_content = "(ไอถ้าคุณเข้าใจ.)",
  ui_story_5020_50200901_104_dialog_content = "*แค่ก*",
  ui_story_5020_50200901_105_dialog_content = "(โอเค ทำต่อไป ทำให้เขายุ่ง)",
  ui_story_5020_50200901_106_dialog_content = "เอ่อ... ท่านลอร์ด สัญญาเช่าฟังฉัน",
  ui_story_5020_50200901_107_dialog_content = "ไปข้างหน้าและตัดแขนขาออก แต่ช่วยเอาหัวฉันไว้ที่คอได้ไหม",
  ui_story_5020_50200901_108_dialog_content = "...",
  ui_story_5020_50200901_109_dialog_content = "ฉันมีสองแขนและสองขา เลือกของคุณ",
  ui_story_5020_50200901_110_dialog_content = "แต่ฉันยังใช้หัวของฉันได้ ดังนั้นฉันจึงอยากเก็บไว้",
  ui_story_5020_50200901_111_dialog_content = "โอเค เรามีซามูไรสามคนที่นี่... และอีกห้าคนที่นั่น มีอีกสองฝั่งตรงข้ามถนน",
  ui_story_5020_50200901_112_dialog_content = "รอง คุณจำทั้งหมดนั้นได้ไหม",
  ui_story_5020_50200901_113_dialog_content = "3 คน... 5 คน... แล้วก็อีก 2 คน...",
  ui_story_5020_50200901_114_dialog_content = "คุณต้องจำมันให้ได้ เราจะไม่ได้รับโอกาสครั้งที่สอง!",
  ui_story_5020_50200901_115_dialog_content = "Anzu และ Momo คลายหัวกลอง เราแค่ต้องดำน้ำผ่านมันไป",
  ui_story_5020_50200901_116_dialog_content = "เมื่อเราผ่านกลองออกไปได้ เราต้องกำจัดซามูไรให้หมด!",
  ui_story_5020_50200901_117_dialog_content = "นี่เป็นทางเดียวที่อันสึกับโมโมะจะมีเวลาแก้มัดพวกโชคุยู",
  ui_story_5020_50200901_118_dialog_content = "ได้เลย! 3 คน... แล้วก็ 5 คน...",
  ui_story_5020_50200901_119_dialog_content = "และหน้าที่ของฉันคือขัดขวางนายพลใช่ไหม?",
  ui_story_5020_50200901_120_dialog_content = "ใช่ ก่อความวุ่นวายให้มากที่สุดเท่าที่คุณจะทำได้",
  ui_story_5020_50200901_121_dialog_content = "เมื่อนายพลสั่งผีให้หยุดเรา ความจริงจะปรากฎ!",
  ui_story_5020_50200901_122_dialog_content = "แล้วหลังจากนั้นล่ะ? เราจะออกไปได้ยังไง?",
  ui_story_5020_50200901_123_dialog_content = "ฉันไม่สามารถวางแผนล่วงหน้าได้ไกลขนาดนั้น เราจะต้องด้นสดหลังจากนั้น!",
  ui_story_5020_50200901_124_dialog_content = "อันสึ โมโมะ พร้อมรึยัง?",
  ui_story_5020_50200901_125_dialog_content = "พร้อมแล้ว!",
  ui_story_5020_50200901_126_dialog_content = "เราตัดเชือกแล้ววิ่งด้วย Wisp ขวา?",
  ui_story_5020_50200901_127_dialog_content = "ถูกต้อง!",
  ui_story_5020_50200901_128_dialog_content = "พวกเขาดูไม่หล่อเลยสักนิด...",
  ui_story_5020_50200901_129_dialog_content = "จะเป็นอันตรายหรือไม่?",
  ui_story_5020_50200901_130_dialog_content = "แจ้งให้เราทราบหากคุณตกอยู่ในอันตราย",
  ui_story_5020_50200901_131_dialog_content = "อย่างเช่น...",
  ui_story_5020_50200901_132_dialog_content = "ตีกลองให้เราได้ยินก็ได้",
  ui_story_5020_50200901_133_dialog_content = "โอ้ใช่! เข้าใจ",
  ui_story_5020_50200901_134_dialog_content = "ฉันชอบการตีกลองสุด ๆ เลย!",
  ui_story_5020_50200901_135_dialog_content = "ตอนนี้ต้องรอให้ Vice จำให้ได้ทั้งหมด...",
  ui_story_5020_50200901_136_dialog_content = "ฉันพร้อมแล้ว!",
  ui_story_5020_50200901_137_dialog_content = "เอาล่ะ!",
  ui_story_5020_50200901_138_dialog_content = "เตรียมพร้อม. สาม...",
  ui_story_5020_50200901_139_dialog_content = "<size=40>สอง...</size>",
  ui_story_5020_50200901_140_dialog_content = "<size=45>หนึ่ง...</size>",
  ui_story_5020_50200901_141_dialog_content = "<size=50>ลุย!</size>",
  ui_story_5020_50200901_142_dialog_content = "<color=#e8d9bb><size=50>ตูม...</size></color>",
  ui_story_5020_50200901_143_dialog_content = "น้ำวนเชี่ยวกราก!",
  ui_story_5020_50200901_144_dialog_content = "ช่วยชีวิตกำมือ! รีบ!",
  ui_story_5020_50200901_145_dialog_content = "รู้แล้วน่า รู้แล้ว!",
  ui_story_5020_50200901_146_dialog_content = "ช่วยด้วย! ตีกันแล้ว!",
  ui_story_5020_50200901_147_dialog_content = "พี่น้องทั้งหลาย จงจับอาวุธขึ้นมา!",
  ui_story_5020_50200901_148_dialog_content = "กบฏ! ปกป้องนายพล!",
  ui_story_5020_50200901_149_dialog_content = "<color=#e8d9bb>กริ๊ง...</color>",
  ui_story_5020_50200901_150_dialog_content = "...",
  ui_story_5020_50200901_151_dialog_content = "...",
  ui_story_5020_50200901_152_dialog_content = "รินเนะ คุณทำผิดพลาดครั้งใหญ่",
  ui_story_5020_50200901_153_dialog_content = "ทำไมล่ะคะ?",
  ui_story_5020_50200901_154_dialog_content = "เพราะนี่เป็นสิ่งที่ผิดน่ะสิ",
  ui_story_5020_50200901_155_dialog_content = "สิ่งที่ถูกและผิดที่คุณสอนฉันนั้นค่อนข้างแตกต่างจากความเชื่อที่แท้จริงของคุณ",
  ui_story_5020_50200901_156_dialog_content = "ฉันสอนทุกอย่างกับเจ้าในคราวเดียวไม่ได้หรอก บางเรื่องก็ต้องใช้เวลาในการทำความเข้าใจ",
  ui_story_5020_50200901_157_dialog_content = "ไม่จำเป็นหรอก ฉันได้คิดใคร่ครวญและเข้าใจอย่างถ่องแท้แล้ว",
  ui_story_5020_50200901_158_dialog_content = "บรรดานักบวชหญิงที่อยู่ต่อหน้าข้าพเจ้า ผู้ที่ทำสิ่งที่ท่านคิดว่าถูกต้อง ตอนนี้พวกเขาอยู่ที่ไหน?",
  ui_story_5020_50200901_159_dialog_content = "พวกเขาสร้าง Koufu-jou ที่คุณเห็นในปัจจุบัน",
  ui_story_5020_50200901_160_dialog_content = "งั้นรึ?",
  ui_story_5020_50200901_161_dialog_content = "ฉันอยากเปลี่ยนแปลงโคฟุโจค่ะ",
  ui_story_5020_50200901_162_dialog_content = "และนี่คือวิธีที่คุณเลือกที่จะทำมัน?",
  ui_story_5020_50200901_163_dialog_content = "ฉันเห็นการจลาจลมากเกินไปในชีวิตของฉัน พวกเขาไม่เคยนำมาซึ่งการเปลี่ยนแปลง—มีเพียงการทำลายล้างเท่านั้น",
  ui_story_5020_50200901_164_dialog_content = "ฉันแน่ใจว่ามีสิ่งที่คุณยังไม่เคยเห็นเช่นกัน",
  ui_story_5020_50200901_165_dialog_content = "เช่นนักบวชหญิงชี้ดาบมาที่คุณ",
  ui_story_5020_50200901_166_dialog_content = "ฉันไม่สนใจว่าคุณจะชี้ดาบไปทางไหน",
  ui_story_5020_50200901_167_dialog_content = "ฉันแค่อยากให้คุณลองคิดดู",
  ui_story_5020_50200901_168_dialog_content = "ฉันคิดเสมอว่าผีเป็นศัตรูคนเดียวของฉัน",
  ui_story_5020_50200901_169_dialog_content = "แต่ในตอนนี้ ฉันต้องเผชิญหน้ากับท่าน",
  ui_story_5020_50200901_170_dialog_content = "และเป็นครั้งแรกที่ฉันรู้สึกเกลียดชังอย่างรุนแรงต่อคนที่มีชีวิต",
  ui_story_5020_50200901_171_dialog_content = "เจ้าควรหวาดกลัวความชิงชังนั่น",
  ui_story_5020_50200901_172_dialog_content = "หึหึ",
  ui_story_5020_50200901_173_dialog_content = "ฉันตื่นเต้นมากกว่ากลัว",
  ui_story_5020_50200902_1_dialog_content = "ฆ่าพวกมันซะ!",
  ui_story_5020_50200902_2_dialog_content = "ไอ้พวกกบฏเหลือขอ!",
  ui_story_5020_50200902_3_dialog_content = "อ่า! พวกเขากำลังฆ่าคน!",
  ui_story_5020_50200902_4_dialog_content = "อย่าตื่นตระหนกไป!",
  ui_story_5020_50200902_5_dialog_content = "จัดกลุ่มใหม่! ล้อมปราบ!",
  ui_story_5020_50200902_6_dialog_content = "ล้อมรอบเรา? ฮึ่ม!",
  ui_story_5020_50200902_7_dialog_content = "ซามูไร ฉันไม่คิดว่าคุณเข้าใจสถานการณ์",
  ui_story_5020_50200902_8_dialog_content = "หากไม่มีภูติผีคอยช่วยเหลือ คุณก็ควบคุมสนามรบแห่งนี้ไม่ได้!",
  ui_story_5020_50200902_9_dialog_content = "ช่างเป็นเรื่องตลก",
  ui_story_5020_50200902_10_dialog_content = "เมื่อไหร่ที่คุณ Wisp ชนะการต่อสู้ ไม่ว่าจะเป็นการต่อสู้กับคนเป็นหรือคนตาย?",
  ui_story_5020_50200902_11_dialog_content = "เราจะครั้งนี้",
  ui_story_5020_50200902_12_dialog_content = "เราควรวิ่งไหม? ฉันไม่อยากตาย...",
  ui_story_5020_50200902_13_dialog_content = "สถานที่ที่จะ? ถ้าออกไปเราอาจเจอผี...",
  ui_story_5020_50200902_14_dialog_content = "ผีตัวแรกฆ่าคน เดี๋ยวนี้คนก็ฆ่าคนเหมือนกัน...",
  ui_story_5020_50200902_15_dialog_content = "จะต้องมีคนตายอีกสักกี่คนกัน?",
  ui_story_5020_50200902_16_dialog_content = "<color=#e8d9bb>ตูม!</color>",
  ui_story_5020_50200902_17_dialog_content = "!!!",
  ui_story_5020_50200902_18_dialog_content = "!!!",
  ui_story_5020_50200902_19_dialog_content = "นั่นมัน...",
  ui_story_5020_50200902_20_dialog_content = "ไม่นะ",
  ui_story_5020_50200902_21_dialog_content = "เมฆสีทองได้บังเกิดส่องแสงลงมายังโลก ผีและวิญญาณทั้งหมดกราบไหว้กษัตริย์ของพวกเขา",
  ui_story_5020_50200902_22_dialog_content = "...",
  ui_story_5020_50200902_23_dialog_content = "ทั่วไป ดูเหมือนว่าคุณจะสอนวิธีใช้ Cloud Mirror ให้ฉันในที่สุด",
  ui_story_5020_50200902_24_dialog_content = "สิ่งที่ฉันต้องการคือความสงบสุข",
  ui_story_5020_50200902_25_dialog_content = "คุณได้รับประโยชน์จากความสงบ แต่คุณไม่เข้าใจมัน",
  ui_story_5020_50200902_26_dialog_content = "ข้าไม่มีเวลามาสอนอะไรให้เจ้าอีกแล้ว",
  ui_story_5020_50200902_27_dialog_content = "วันนี้ Koufu-jou จะรู้จักความสงบสุข",
  ui_story_5020_50200902_28_dialog_content = "ไม่ว่าคุณจะชอบมันหรือไม่ก็ตาม",
  ui_story_5020_50200902_29_dialog_content = "...",
  ui_story_5020_50200902_30_dialog_content = "...",
