  ui_story_5020_50200902_48_dialog_content = "ฮึ่ม! หมาป่าในชุดแกะ!",
  ui_story_5020_50200902_49_dialog_content = "คุณกำลังปิดผนึกถนน? แล้วพลเรือนล่ะ?",
  ui_story_5020_50200902_50_dialog_content = "นี่คือการรักษาความสงบเรียบร้อยในแบบของข้า",
  ui_story_5020_50200902_51_dialog_content = "ผู้ที่ปฏิบัติตามกฎจะได้พบความสงบสุข ผู้ที่ละเมิดกฎจะต้องถูกลงโทษ",
  ui_story_5020_50200902_52_dialog_content = "รักษาความสงบด้วยวิญญาณร้ายเนี่ยนะ?",
  ui_story_5020_50200902_53_dialog_content = "คุณทำมันหาย...",
  ui_story_5020_50200902_54_dialog_content = "ผี คน... ไม่ต่างกันเลย",
