  ui_story_5020_50200902_57_dialog_content = "รินเนะ ลืมเขาไปก่อน",
  ui_story_5020_50200902_58_dialog_content = "กองพลโชคุยูพยายามพาชาวเมืองตีฝ่าออกไป แต่...",
