  ui_story_5020_50200902_61_dialog_content = "ผมมีวิธี",
  ui_story_5020_50200902_62_dialog_content = "คุณจะต้องช่วยพวกเขา",
  ui_story_5020_50200902_63_dialog_content = "ฉัน? แล้วสถานการณ์ที่นี่ล่ะ?",
