  ui_story_5020_50200902_66_dialog_content = "ใช่ ฉันก็ไม่แน่ใจเหมือนกันว่าเราจะยื้อได้นานมั้ย แต่เราไม่มีเวลาแล้ว",
  ui_story_5020_50200902_67_dialog_content = "รินเนะ ไม่มีใครปราบผีได้ดีกว่าเธอแล้ว มันจะต้องมีคุณ.",
