  ui_story_5020_50201001_46_dialog_content = "ไม่ ไม่... มีเรื่องเกิดขึ้น และรินเนะต่อสู้เคียงบ่าเคียงไหล่กับ Wisp",
  ui_story_5020_50201001_47_dialog_content = "สำหรับตอนนี้ สมมติว่าพวกเขาอยู่ข้างเรา",
  ui_story_5020_50201001_48_dialog_content = "โชคุยูกับมิโกะอยู่ฝ่ายเดียวกัน?",
