  ui_story_5020_50201001_52_dialog_content = "... สบายดี ฉันเข้าใจ",
  ui_story_5020_50201001_53_dialog_content = "เธอจะทำให้พลเรือนปลอดภัย อย่างน้อยก็ชั่วขณะหนึ่ง",
  ui_story_5020_50201001_54_dialog_content = "ฉันต้องไปหาบางอย่าง",
  ui_story_5020_50201001_55_dialog_content = "อะไรเหรอ?",
  ui_story_5020_50201001_56_dialog_content = "ดาบพิฆาตวิญญาณ—<color=#FFB400>ชิ้นแห่งสวรรค์</color>.",
