  ui_story_5020_50201101_2_dialog_content = "ฟู่...",
  ui_story_5020_50201101_3_dialog_content = "ซามูไรผีเยอะมาก...",
  ui_story_5020_50201101_4_dialog_content = "ฟูจิคุโมะเอาจริงแล้วสินะ",
