  ui_story_5020_50201101_7_dialog_content = "<anim type=Shake>กรร...</anim>",
  ui_story_5020_50201101_8_dialog_content = "<size=45><anim type=Shake>กรรรร!</anim></size>",
  ui_story_5020_50201101_9_dialog_content = "T-ผีเหล่านี้ไม่สามารถฆ่าได้!",
  ui_story_5020_50201101_10_dialog_content = "มีแต่รินเนะเท่านั้นที่จัดการกับมันได้",
  ui_story_5020_50201101_11_dialog_content = "<size=45><anim type=Shake>กรรรรรร!</anim></size>",
  ui_story_5020_50201101_12_dialog_content = "ย้ากก!",
  ui_story_5020_50201101_13_dialog_content = "เราอาจไม่สามารถทำลายพวกมันได้ แต่เรายังสามารถผลักพวกมันกลับไปได้!",
  ui_story_5020_50201101_14_dialog_content = "ฟ้าดินประสานเป็นหนึ่ง บุกหน้าเหมือนผ่าลำไผ่!",
  ui_story_5020_50201101_15_dialog_content = "<anim type=Shake>กรร...</anim>",
  ui_story_5020_50201101_16_dialog_content = "แต่กลับ...",
