  ui_story_5020_50201101_18_dialog_content = "!!!",
  ui_story_5020_50201101_19_dialog_content = "<size=45><anim type=Shake>โฮกก!</anim></size>",
  ui_story_5020_50201101_20_dialog_content = "H-เขา...ได้ยังไง?!",
  ui_story_5020_50201101_21_dialog_content = "ผีซามูไรกำลังหนีจากไฟไหม้ในปราสาท",
