  ui_story_5020_50201101_23_dialog_content = "คราวนี้เขากลั้นไม่อยู่จริงๆ",
  ui_story_5020_50201101_24_dialog_content = "วิชานินจาจงเจริญ!",
  ui_story_5020_50201101_25_dialog_content = "เราต้องออกจาก Sakai เดี๋ยวนี้ และกำจัดผู้ไล่ล่าที่น่ารังเกียจเหล่านี้",
  ui_story_5020_50201101_26_dialog_content = "<color=#e8d9bb>ใกล้สุสานในอาณาเขตนอกโคฟุโจ</color>",
  ui_story_5020_50201101_27_dialog_content = "โอ๊ะ!",
  ui_story_5020_50201101_28_dialog_content = "PlayerName ความทรงจำเก่า ๆ ของฉันกลับคืนมาอีกแล้ว!",
  ui_story_5020_50201101_29_dialog_content = "ฉันเคยมาที่นี่!",
  ui_story_5020_50201101_30_dialog_content = "คุณเคยมาที่นี่มาก่อน...",
  ui_story_5020_50201101_31_dialog_content = "นี่คือที่ที่เราได้พบกับ Rinne และ Amemori เป็นครั้งแรก!",
  ui_story_5020_50201101_32_dialog_content = "ใช่แล้ว โคลอสซัสลงจอดฉุกเฉินหลังจากที่เรามาถึงเกาะเมฆา...",
  ui_story_5020_50201101_32X_dialog_content = "เราเจอรินเนะในป่าไผ่ข้างหน้าแล้วก็...",
  ui_story_5020_50201101_33_dialog_content = "Amemori ที่ต้องต่อสู้กับเราก่อนที่เธอจะเป็นเพื่อนของเรา!",
  ui_story_5020_50201101_34_dialog_content = "...",
  ui_story_5020_50201101_35_dialog_content = "ฮะ! ก็ถึงว่า ทำไมรู้สึกคุ้น ๆ!",
  ui_story_5020_50201101_36_dialog_content = "... \"ตามแม่น้ำสายนี้ไปทางตะวันตกผ่านหมู่บ้านนาข้าวก็จะถึงสุสานบนภูเขา\"",
  ui_story_5020_50201101_37_dialog_content = "ตามความทรงจำเรามาถูกทางแล้ว!",
  ui_story_5020_50201101_38_dialog_content = "นี่ อาเมะโมริ อย่ามาขวางทางฉันอีกล่ะ เข้าใจมั้ย?",
  ui_story_5020_50201101_39_dialog_content = "ฮะ! นั่นคือสายของฉัน",
  ui_story_5020_50201101_40_dialog_content = "Slice of Heaven—ดาบสังหารผีเป็นความหวังเดียวของเราในการต่อสู้กับผีซามูไรของฟูจิคุโมะ",
  ui_story_5020_50201101_41_dialog_content = "ฉันไม่ได้หวังให้คุณช่วย แค่อย่ามาขวางทาง",
  ui_story_5020_50201101_42_dialog_content = "เดี๋ยวสิ! พูดอย่างนี้หมายความว่าไง",
  ui_story_5020_50201101_43_dialog_content = "คุณกำลังพยายามที่จะใช้ Slice of Heaven ด้วยตัวคุณเองหรือไม่?",
  ui_story_5020_50201101_44_dialog_content = "ถูกต้อง",
  ui_story_5020_50201101_45_dialog_content = "แต่... แต่มันไม่ใช่ของคุณ... Slice of Heaven คือ...",
  ui_story_5020_50201101_46_dialog_content = "มันเป็นของนักบวชหญิงผู้ล่วงลับไปแล้ว!",
  ui_story_5020_50201101_47_dialog_content = "ฉันไม่สนใจอะไรทั้งนั้น ฉันต้องการมันเพื่อปกป้องผู้บริสุทธิ์ของ Koufu-jou",
  ui_story_5020_50201101_48_dialog_content = "ว้าว! คุณกลายเป็นคนประเภทสุนทรพจน์ที่ยิ่งใหญ่ตั้งแต่เมื่อไหร่?",
  ui_story_5020_50201101_49_dialog_content = "คุณจะทำเช่นเดียวกันถ้าอาจารย์ไม่เกลียดนักบวชหญิงคนนั้น?",
  ui_story_5020_50201101_50_dialog_content = "(พี่น้องคู่นี้ช่างตรงกันข้ามจริงๆ...)",
  ui_story_5020_50201101_51_dialog_content = "คุณสองคน... ได้โปรดหยุดโต้เถียง!",
  ui_story_5020_50201101_52_dialog_content = "...หา?",
  ui_story_5020_50201101_53_dialog_content = "หืม...?",
  ui_story_5020_50201101_54_dialog_content = "ว้าว... หิมะตกเหรอ?",
  ui_story_5020_50201101_55_dialog_content = "ไม่ ไม่ใช่หิมะ เหล่านี้คือ...",
  ui_story_5020_50201101_56_dialog_content = "<color=#FFB400>ดอกซากุระสีขาว</color>เหรอ?",
  ui_story_5020_50201101_57_dialog_content = "กลีบดอกสีขาวเล็กๆ เหล่านี้ร่วงหล่นอย่างอ่อนโยน... พวกมันดูเหมือนเกล็ดหิมะ!",
  ui_story_5020_50201101_58_dialog_content = "\"คนในท้องถิ่นของ Cloud Island ชอบดอกซากุระที่อวบอิ่มและมีสีสันสดใส...\"",
  ui_story_5020_50201101_59_dialog_content = "ฮะ นี่มันแตกต่างจากหนังสือนำเที่ยวอย่างสิ้นเชิง!",
  ui_story_5020_50201101_60_dialog_content = "ที่นี่อาจเป็นที่เดียวบนเกาะเมฆาที่มีซากุระชนิดนี้...",
  ui_story_5020_50201101_61_dialog_content = "เรากำลังขึ้นไปบนสุสาน",
  ui_story_5020_50201101_62_dialog_content = "อืม... ไม่แปลกใจเลยว่าทำไมที่นี่ถึงเงียบ...",
  ui_story_5020_50201101_63_dialog_content = "<anim type=Shake>กรรรร...</anim>",
  ui_story_5020_50201101_64_dialog_content = "เอ่อ... ไม่มีทาง...",
  ui_story_5020_50201101_65_dialog_content = "<anim type=Shake>กรรรร!</anim>",
  ui_story_5020_50201101_66_dialog_content = "ไม่มีที่ไหนที่สิ่งเหล่านี้จะไม่ไป?!",
  ui_story_5020_50201101_67_dialog_content = "มันคือสุสาน ดังนั้นฉันเดาว่ามันไม่ได้คาดคิดมาก่อน...",
  ui_story_5020_50201101_68_dialog_content = "คุยกันก็พอ ถึงเวลาที่ฉันต้องออกหมัดแล้ว!",
  ui_story_5020_50201201_1_dialog_content = "น้ำวนเชี่ยวกราก!",
  ui_story_5020_50201201_2_dialog_content = "<anim type=Shake>เอิ๊ก...</anim>",
  ui_story_5020_50201201_3_dialog_content = "วุ้ย... อะไรพวกนี้ช่างน่ารำคาญเสียจริง!",
  ui_story_5020_50201201_4_dialog_content = "แต่คุณรู้ไหมว่าพวกเขาพูดว่าอย่างไร ดึงแครอทออกมาไม่ได้โดยที่ไม่มีสิ่งสกปรกเช่นกัน!",
  ui_story_5020_50201201_5_dialog_content = "...ใครว่ากันแน่?",
  ui_story_5020_50201201_6_dialog_content = "น้องสาวร่วมสาบานของฉัน! เธอมีคำพูดสำหรับทุกโอกาสและเธอก็ชนะทุกข้อโต้แย้งในตระกูล Lin!",
  ui_story_5020_50201201_7_dialog_content = "แน่นอน เธอชนะทุกครั้งเช่นกัน!",
  ui_story_5020_50201201_8_dialog_content = "เธอดูเป็นตัวละครที่ค่อนข้าง...",
  ui_story_5020_50201201_9_dialog_content = "อย่างนี้นี่เอง ไม่แปลกใจเลย",
  ui_story_5020_50201201_10_dialog_content = "หืม? ไม่แปลกใจอะไร? ไม่น่าแปลกใจที่ฉันดีมาก?",
  ui_story_5020_50201201_11_dialog_content = "ไม่น่าแปลกใจเลยที่คุณกลายเป็นคนกักขฬะ",
  ui_story_5020_50201201_12_dialog_content = "น่าเสียดายที่เห็นการฝึกปรมาจารย์สูญเปล่าเช่นนี้",
  ui_story_5020_50201201_13_dialog_content = "เมื่อกี้คืออะไร? พูดอีกครั้ง!",
  ui_story_5020_50201201_14_dialog_content = "PlayerNameคุณได้ยินว่าเธอคุยกับรุ่นน้องของเธออย่างไร?",
  ui_story_5020_50201201_15_dialog_content = "เอาล่ะ เหยา พอเถอะ",
  ui_story_5020_50201201_16_dialog_content = "เธอก็ด้วย อาเมะโมริ ไม่น่าไปแหย่ศิษย์น้องเล๊ย",
  ui_story_5020_50201201_17_dialog_content = "อะไร ฉันไม่ได้ล้อเล่น!",
  ui_story_5020_50201201_18_dialog_content = "แล้วถ้าเป็นคุณล่ะ!?",
  ui_story_5020_50201201_19_dialog_content = "คุณกำลังบอกว่าคุณกลัวฉันเกินกว่าจะแกล้งฉันเหรอ?",
