  ui_story_5020_50201201_21_dialog_content = "ให้ฉันทำสิ่งหนึ่งให้ชัดเจน",
  ui_story_5020_50201201_22_dialog_content = "ฉันจะไม่ออกจากสุสานนี้หากไม่มี Slice of Heaven",
  ui_story_5020_50201201_23_dialog_content = "คุณอาจแก้ตัวได้มากเท่าที่คุณต้องการ...",
  ui_story_5020_50201201_24_dialog_content = "แต่สุดท้ายก็จำอาจารย์แทบไม่ได้ ทั้งหมดที่คุณพูดถึงคือน้องสาวร่วมสาบานของคุณ",
  ui_story_5020_50201201_25_dialog_content = "ฉันได้รับการเลี้ยงดูจากท่านอาจารย์",
  ui_story_5020_50201201_26_dialog_content = "ฉันต้องได้รับ Slice of Heaven เพื่อช่วย Master เอาชนะ Fujikumo",
  ui_story_5020_50201201_27_dialog_content = "(ถึงแม้อาจารย์จะไม่เคยขอให้ผมทำอะไรให้เธอก็ตาม...)",
  ui_story_5020_50201201_28_dialog_content = "แม้ว่าอาจารย์จะไม่ได้บอกเธอถึงแผนการของเธอที่จะจุดไฟเผาทั้งเมือง?",
  ui_story_5020_50201201_29_dialog_content = "โอย...",
  ui_story_5020_50201201_30_dialog_content = "อาจารย์ก็มีเหตุผลของอาจารย์!",
  ui_story_5020_50201201_31_dialog_content = "แน่นอนเธอทำ แต่คุณรู้จักเธอมากแค่ไหน?",
  ui_story_5020_50201201_32_dialog_content = "?!",
  ui_story_5020_50201201_33_dialog_content = "คุณ... คุณจำอะไรเกี่ยวกับเธอที่ฉันไม่รู้ได้ไหม?",
  ui_story_5020_50201201_34_dialog_content = "... ฉันได้แบ่งปันทุกสิ่งที่ฉันรู้กับคุณแล้ว",
  ui_story_5020_50201201_35_dialog_content = "แต่ผู้ที่เป็นเจ้าของ Slice of Heaven มีความหมายอย่างมากต่อ Master",
  ui_story_5020_50201201_36_dialog_content = "...",
  ui_story_5020_50201201_37_dialog_content = "นั่นสินะ... ฉันไม่เข้าใจเลย",
  ui_story_5020_50201201_37X_dialog_content = "อาจารย์ให้ความสำคัญกับชื่อเสียงของเธอมาก... ทำไมเธอถึงทำให้มือของเธอสกปรก?",
  ui_story_5020_50201201_38_dialog_content = "เฮ้ นอกจากนี้...",
  ui_story_5020_50201201_39_dialog_content = "ฉันแน่ใจว่านักบวชหญิงเป็นบุคคลที่สำคัญมาก ฉันสามารถบอกได้จากความทรงจำของฉัน",
  ui_story_5020_50201201_40_dialog_content = "ทำไมถึงมั่นใจขนาดนั้น?",
  ui_story_5020_50201201_41_dialog_content = "ลางสังหรณ์มันบอก!",
  ui_story_5020_50201201_42_dialog_content = "...",
  ui_story_5020_50201201_43_dialog_content = "เป็นอะไรกับหน้า? สัญชาตญาณของฉันไม่เคยผิดพลาด!",
  ui_story_5020_50201201_44_dialog_content = "เรื่องนี้ผมยืนยันได้",
  ui_story_5020_50201201_45_dialog_content = "ชอบหรือไม่ ฉันกำลังเอา Slice of Heaven",
  ui_story_5020_50201201_46_dialog_content = "ฉันแน่ใจว่ามันจะช่วยให้ฉันจำสิ่งต่างๆ ได้มากขึ้น",
  ui_story_5020_50201201_47_dialog_content = "เรื่องของอาจารย์!",
  ui_story_5020_50201201_48_dialog_content = "อย่างไรก็ตาม ฉันไม่ได้คาดหวังความช่วยเหลือจากคุณ อย่ามาขวางทางฉัน!",
  ui_story_5020_50201201_49_dialog_content = "...",
  ui_story_5020_50201201_50_dialog_content = "... หืม?",
  ui_story_5020_50201201_51_dialog_content = "<color=#e8d9bb>ฟึบ...</color>",
  ui_story_5020_50201201_52_dialog_content = "คุไน!",
  ui_story_5020_50201201_53_dialog_content = "<anim type=Shake>กรรรร...</anim>",
  ui_story_5020_50201201_54_dialog_content = "เหยา คุณต้องให้พวกคุณสิบคนมาเซอร์ไพรส์ฉัน",
