  ui_story_5020_50201201_60_dialog_content = "<anim type=Shake>เอิ๊ก...</anim>",
  ui_story_5020_50201201_61_dialog_content = "ลำดับความสำคัญของเราควรกำจัดผีร้ายเหล่านี้!",
