  ui_story_5020_50201202_2_dialog_content = "ฮึ่ม! พวกกระจอกเอ๊ย!",
  ui_story_5020_50201202_3_dialog_content = "คอยเตือนทุกคน จะมีวิญญาณมากขึ้นในสุสาน",
