  ui_story_5020_50201202_7_dialog_content = "<color=#e8d9bb>หวด...หวู่...</color>",
  ui_story_5020_50201202_8_dialog_content = "หัวใจของฉันกำลังเต้นแรง... ความเงียบงันนี้กำลังทำให้ฉันคลั่งไคล้",
  ui_story_5020_50201202_9_dialog_content = "อย่ากลัว ไม่มีปัญหาใดที่แก้ไม่ได้ด้วยกำปั้น!",
