  ui_story_5020_50201301_68_dialog_content = "ฉันก็เป็นแค่เครื่องมืออีกชิ้นที่ช่วยพาเกาะเมฆาไปสู่ความสงบสุขชั่วกาลนาน",
  ui_story_5020_50201301_69_dialog_content = "ท่านหญิงนักบวช... ข้า...",
  ui_story_5020_50201301_70_dialog_content = "ผมว่าผมคิดตามไม่ทันแล้วล่ะ!",
  ui_story_5020_50201301_71_dialog_content = "<color=#e8d9bb>กริ๊ง... กริ๊ง...กริ๊ง...</color>",
  ui_story_5020_50201301_72_dialog_content = "หึหึ ดู! เกี้ยวของท่านคุโบะประดับด้วยระฆังมากมาย!",
  ui_story_5020_50201301_73_dialog_content = "อ๊ะ... ท่านคุโบ!",
  ui_story_5020_50201301_74_dialog_content = "Lady Priestess ถ้าคุณสามารถขอโทษได้... ฉันต้องดูแลความปลอดภัยของ Kubou-sama!",
  ui_story_5020_50201301_75_dialog_content = "<color=#e8d9bb>กริ๊ง... กริ๊ง...กริ๊ง...</color>",
  ui_story_5020_50201301_76_dialog_content = "อย่าไล่ฉัน! อย่าไล่ฉัน!",
  ui_story_5020_50201301_77_dialog_content = "นี่... เจ้าเด็กดื้อ คืนกระดิ่งคางุระให้สึกิได้แล้ว!",
  ui_story_5020_50201301_78_dialog_content = "ฉันต้องการน้องสาวของฉันไล่ล่าฉัน! ฉันจะเอาคืนถ้าเธอจับฉันได้!",
  ui_story_5020_50201301_79_dialog_content = "คุณ... ฉันต้องบอกคุณกี่ครั้ง? เธอเป็นนักบวช ไม่ใช่น้องสาวของคุณ!",
  ui_story_5020_50201301_80_dialog_content = "โอเค ได้เลย!",
  ui_story_5020_50201301_81_dialog_content = "อย่าไปถือสาเลย นากิ เธอยังเด็กนะ",
  ui_story_5020_50201301_82_dialog_content = "เหยาเรียกฉันว่าพี่สาวเพราะเธอชอบฉัน",
  ui_story_5020_50201301_83_dialog_content = "...แต่คุณเหมือนน้องสาวฉัน เหยาเป็นลูกบุญธรรมของคุณ",
  ui_story_5020_50201301_84_dialog_content = "ถ้าเธอยังเรียกคุณว่าน้องสาว นั่นทำให้ฉันเป็นอะไร",
  ui_story_5020_50201301_85_dialog_content = "หึ ๆ ๆ",
  ui_story_5020_50201301_86_dialog_content = "นี่ไม่ตลกนะ!",
  ui_story_5020_50201301_87_dialog_content = "ดี. ฉันรู้ว่าเย้าเป็นคนซน แต่อาเมโมริเป็นเด็กดี",
  ui_story_5020_50201301_88_dialog_content = "ฉันขอให้คุณช่วยดูแลพวกเขาสองคน และคุณก็เปลี่ยนอาเมะโมริให้เป็นคุณในเวอร์ชั่นย่อส่วน",
  ui_story_5020_50201301_89_dialog_content = "อืม... เธอเรียนรู้เร็วจัง",
  ui_story_5020_50201301_90_dialog_content = "ฉันอดไม่ได้ที่จะสอนสิ่งใหม่ ๆ ให้เธอ",
