  ui_story_5020_50201301_92_dialog_content = "ไม่ต้องกังวล. ฉันจะไม่สอนทักษะเหล่านี้โดยไม่ได้รับอนุญาตจากคุณ",
  ui_story_5020_50201301_93_dialog_content = "อีกอย่าง ฉันคิดว่าอาเมโมริแบกภาระหนักๆ ไว้บนไหล่เล็กๆ ของเธอแล้ว...",
  ui_story_5020_50201301_94_dialog_content = "เธอยังเด็กมาก แต่เธอก็จงใจทำตัวแข็งกร้าวและไม่แยแส...",
