  ui_story_5020_50201401_59_dialog_content = "ไม่ใช่แค่ท่านอาจารย์เท่านั้น พระศาสดาก็เหมือนกัน...",
  ui_story_5020_50201401_60_dialog_content = "พวกเขาทั้งคู่รู้ว่าต้องการทำอะไรในช่วงเวลาใดเวลาหนึ่ง",
  ui_story_5020_50201401_61_dialog_content = "ดังนั้น อาเมโมริ... ถ้าท่านต้องละทิ้งอิทธิพลของอาจารย์และความกดดันทั้งหมดที่ท่านมีต่อตนเอง...",
