  ui_story_5020_50201401_64_dialog_content = "ทิ้งทั้งหมดนั้นไว้ ฉัน...",
  ui_story_5020_50201401_65_dialog_content = "ไม่รู้สิ...",
  ui_story_5020_50201401_66_dialog_content = "<color=#e8d9bb>ปึง...</color>",
  ui_story_5020_50201401_67_dialog_content = "<color=#e8d9bb>ปึง... ปึง!</color>",
  ui_story_5020_50201401_68_dialog_content = "เสียงอะไรน่ะ?!",
