  ui_story_5020_50201401_70_dialog_content = "แต่ทำไม? Koufu-jou ได้ลงมาสู่ความโกลาหลแล้ว ...",
  ui_story_5020_50201401_71_dialog_content = "มันเป็นสัญญาณ สองคนนั้นกำลังบอกว่ารินเนะตกอยู่ในอันตราย!",
  ui_story_5020_50201401_72_dialog_content = "รินเนะ!",
  ui_story_5020_50201401_73_dialog_content = "เธออยู่ไหน?",
  ui_story_5020_50201401_74_dialog_content = "... ฉันจะส่ง Wisp ไปช่วย!",
  ui_story_5020_50201401_75_dialog_content = "ไม่ต้องหรอก!",
  ui_story_5020_50201401_75X_dialog_content = "รินเนะอยู่กับวิสป์ตั้งแต่รินเนะจากเราไป",
  ui_story_5020_50201401_76_dialog_content = "ฉันเดาว่าพวกเขากำลังต่อสู้ในสมรภูมิใหม่ด้วยกัน",
  ui_story_5020_50201401_77_dialog_content = "ต่อสู้ด้วยกัน? เป็นไปได้ยังไงน่ะ?",
  ui_story_5020_50201401_78_dialog_content = "อาเมะโมริ... บางครั้ง ทางเลือกเดียวของคุณก็ยังเป็นทางเลือกอยู่ดี",
  ui_story_5020_50201401_79_dialog_content = "ในช่วงเวลาที่สำคัญนี้ คุณต้องรู้ว่าคุณต้องการทำอะไรอย่างแท้จริง!",
  ui_story_5020_50201401_80_dialog_content = "...",
  ui_story_5020_50201401_81_dialog_content = "เสียงมาจากท่าเรือ",
