  ui_story_5020_50201401_83_dialog_content = "เนื่องจากสิ่งนี้มีความทรงจำของเราเมื่อสิบปีที่แล้ว ให้ใช้มันเพื่อนำเรื่องราวที่เริ่มขึ้นในตอนนั้นมาสู่บทสรุป",
