  ui_story_5020_50201401_89_dialog_content = "เร็วเข้า! ถอยเร็วเข้า!",
  ui_story_5020_50201401_90_dialog_content = "คนที่ท่าเรือจะพาคุณไปอย่างปลอดภัย",
