  ui_story_5020_50201401_92_dialog_content = "นี่มันบ้าไปแล้ว...",
  ui_story_5020_50201401_93_dialog_content = "อดีตกองทัพกบฏของดาบแห่งยมโลกร่วมมือกับมิโกะของโชกุน...",
  ui_story_5020_50201401_93X_dialog_content = "...? หา?!",
  ui_story_5020_50201401_94_dialog_content = "โอ๊ย ก้นฉัน!",
  ui_story_5020_50201401_95_dialog_content = "ระวังปาก! หรือครั้งหน้าจะไม่โดนจับ!",
