  ui_story_5020_50201401_98_dialog_content = "ทำไมเราต้องตามเธอด้วย!",
  ui_story_5020_50201401_99_dialog_content = "เธอเป็นคนทรยศ เธอจะขายเราที่เกาะหลัก!",
