  ui_story_5020_50201401_100X_dialog_content = "ไม่นะ!!",
  ui_story_5020_50201401_101_dialog_content = "อุ๊ย...อ๊าาา! ไหล่ของฉัน...",
  ui_story_5020_50201401_102_dialog_content = "พ่อ!",
  ui_story_5020_50201401_103_dialog_content = "เฮ้พรรคพวก! คุณกำลังอพยพพวกเราหรือพยายามที่จะฆ่า...?",
  ui_story_5020_50201401_104_dialog_content = "หือ?",
  ui_story_5020_50201401_105_dialog_content = "<anim type=Shake>กรร...กรรรร!!</anim>",
  ui_story_5020_50201401_106_dialog_content = "ผี... มีผีในซาคาอิด้วย...",
  ui_story_5020_50201401_107_dialog_content = "จับกลุ่มกันไว้ อย่าตื่นตระหนก!",
  ui_story_5020_50201401_108_dialog_content = "มิโกะ เธอนำหน้าไป เดี๋ยวฉันระวังด้านหลังให้!",
