  ui_story_5020_50201501_1_dialog_content = "<color=#e8d9bb>ใกล้ท่าเรือเมืองโคฟุโจ</color>",
  ui_story_5020_50201501_2_dialog_content = "<color=#e8d9bb>ปึง... ปึง!</color>",
