  ui_story_5020_50201501_8_dialog_content = "เหยา!",
  ui_story_5020_50201501_9_dialog_content = "อา! และอาเมะโมริ รอง และ PlayerName!",
  ui_story_5020_50201501_10_dialog_content = "พวกคุณได้ยินเสียงกลองจริง ๆ ด้วย!",
  ui_story_5020_50201501_11_dialog_content = "PlayerName มีหูแหลม! เรามาเร็วที่สุดเท่าที่จะทำได้",
  ui_story_5020_50201501_12_dialog_content = "สถานการณ์เป็นไงบ้าง? เธอบาดเจ็บรึเปล่า?",
