  ui_story_5020_50201501_14_dialog_content = "The Wisp ได้นำพลเรือนบางส่วนขึ้นเรือไปยังที่ปลอดภัยแล้ว...",
  ui_story_5020_50201501_15_dialog_content = "แล้วเธอล่ะ? พวกนั้นสร้างปัญหาให้เธอรึเปล่า?",
  ui_story_5020_50201501_16_dialog_content = "หึหึ ดีใจที่ได้ยินว่าคุณเป็นห่วงฉัน เหยา",
  ui_story_5020_50201501_17_dialog_content = "ไม่ต้องห่วง ฉันสบายดี แล้วทุกคนล่ะ?",
  ui_story_5020_50201501_18_dialog_content = "เรามีความหลังของกันและกัน ดังนั้นเราทุกคนสบายดี! PlayerName, อย่างรวดเร็ว. แสดงให้เธอเห็น <color=#FFB400>สิ่ง</color> เราพบว่า!",
  ui_story_5020_50201501_19_dialog_content = "หืม?",
  ui_story_5020_50201501_20_dialog_content = "สิ่งของ? โอ้ใช่!",
  ui_story_5020_50201501_21_dialog_content = "รินเนะ มีคนฝากสิ่งนี้ให้คุณ",
  ui_story_5020_50201501_22_dialog_content = "โอ้! มันคือ... จดหมายในสมุดบันทึก?",
  ui_story_5020_50201501_23_dialog_content = "จดหมายถึงฉัน? แต่ฉันไม่เคยรู้จักคนชื่อนี้มาก่อนนะ...",
