  ui_story_5020_50201501_26_dialog_content = "สำหรับพระสงฆ์องค์ต่อไป...",
  ui_story_5020_50201501_27_dialog_content = "ฉันตัดสินใจเขียนความคิดในขณะที่รอเธอ",
  ui_story_5020_50201501_28_dialog_content = "ไม่สบายใจกับอนาคตที่จะไม่ได้อยู่ดู...",
  ui_story_5020_50201501_29_dialog_content = "ยิ่งคิดก็ยิ่งเป็นห่วงท่านผู้สืบทอด",
  ui_story_5020_50201501_30_dialog_content = "ไม่ยุติธรรมที่คุณต้องรับตำแหน่งนี้โดยไม่มีที่ปรึกษา",
  ui_story_5020_50201501_31_dialog_content = "มีหลายสิ่งที่ไม่ยุติธรรมและไม่ยุติธรรมที่มาพร้อมกับสถานะนักบวช",
  ui_story_5020_50201501_32_dialog_content = "ไม่รู้ว่าฤดูไหนบนเกาะเมฆาเมื่อเปิดจดหมายฉบับนี้...",
  ui_story_5020_50201501_33_dialog_content = "Cloud Island เป็นที่รู้จักจากดอกซากุระที่บานสะพรั่งราวกับเมฆสีดอกกุหลาบ...",
  ui_story_5020_50201501_33X_dialog_content = "และตกลงมาเหมือนหิมะ",
  ui_story_5020_50201501_34_dialog_content = "สำหรับชาวเกาะเมฆาส่วนใหญ่ มิโกะอย่างพวกเรานั้นงดงาม แต่ก็มีชีวิตอันแสนสั้นเหมือนดอกซากุระ",
  ui_story_5020_50201501_35_dialog_content = "แต่สำหรับฉัน นักบวชหญิงแห่งเกาะเมฆาเปรียบเสมือนดวงอาทิตย์ โดดเดี่ยวแต่งดงามอย่างยิ่ง คอยปกป้องดินแดนแห่งนี้...",
  ui_story_5020_50201501_36_dialog_content = "เราต่อสู้กับค่ำคืนอันมืดมิด แต่เราไม่สามารถปล่อยให้เมฆจากเกาะหลักขวางลำแสงของเราได้",
  ui_story_5020_50201501_37_dialog_content = "อย่างไรก็ตาม หากคุณได้เรียนรู้เกี่ยวกับส่วนนี้ของประวัติศาสตร์แล้ว ฉันน่าจะบอกคุณสองสามเรื่อง นักบวชหญิงคนหนึ่งกับอีกคนหนึ่ง",
  ui_story_5020_50201501_38_dialog_content = "Kubou-sama ไม่ใช่หนึ่งในเมฆมืดเหล่านั้น อย่างน้อยก็ไม่ใช่ในความคิดของฉัน",
  ui_story_5020_50201501_39_dialog_content = "เขาอยู่ใกล้มากขึ้นเหมือนร่มที่บินอยู่เหนือหัวของเรา",
  ui_story_5020_50201501_40_dialog_content = "เขาไม่ใช่คนดี และเขายังไม่ได้ทำสิ่งดีๆ มากมาย แท้จริงแล้วพระองค์ได้นำความทุกข์ยากและความโชคร้ายมาสู่เมืองนี้เป็นอันมาก...",
