  ui_story_5020_50201501_67_dialog_content = "หากคุณไม่พูดอะไร Wisp จะเลือกผู้บัญชาการคนใหม่",
  ui_story_5020_50201501_68_dialog_content = "... ฉันไม่มีอะไรจะพูดกับรินเนะมากนัก",
  ui_story_5020_50201501_69_dialog_content = "โถ... เย็นชาจังเลยนะ",
  ui_story_5020_50201501_70_dialog_content = "อาเมโมริ ไม่นานมานี้ คุณคิดถึงฉันไหม",
  ui_story_5020_50201501_71_dialog_content = "ไม่นานเท่าไรนักหรอก",
  ui_story_5020_50201501_72_dialog_content = "นี่ไม่ใช่เวลามาระลึกถึงอดีต!",
  ui_story_5020_50201501_73_dialog_content = "อ๊ะ! ท่านแม่ทัพ!",
  ui_story_5020_50201501_74_dialog_content = "<size=45>ท่านอาเมะโมริ!</size>",
  ui_story_5020_50201501_75_dialog_content = "ฉันพูดเสมอ อย่าเรียกฉันว่าผู้บัญชาการ!",
  ui_story_5020_50201501_76_dialog_content = "ท่านแม่ทัพอาเมะโมริ เธอสอนกองพลโชคุยูได้ดีมากเลยนะ",
  ui_story_5020_50201501_77_dialog_content = "เราทำงานร่วมกันได้ดีมาก",
  ui_story_5020_50201501_78_dialog_content = "ว้าว มาเลย! Rinne และ Amemori ควรจะประลองกันอย่างเหมาะสม!",
  ui_story_5020_50201501_79_dialog_content = "การต่อสู้ชิงตำแหน่งแม่ทัพของโชคุยูได้เริ่มต้นขึ้นแล้ว!",
  ui_story_5020_50201501_80_dialog_content = "อุ๊ย! หัวของฉัน!",
  ui_story_5020_50201501_81_dialog_content = "เพ้อเจ้ออะไรของเธอเนี่ย?",
  ui_story_5020_50201501_82_dialog_content = "เอาล่ะ ล้อเล่นกันมามากพอแล้ว",
  ui_story_5020_50201501_83_dialog_content = "ผีเคลื่อนไหวอย่างรวดเร็ว ใช้เวลาไม่นานนักก็มาถึงท่าเรือ",
  ui_story_5020_50201501_84_dialog_content = "PlayerName, แยกย้ายเตรียมตัวให้พร้อมก่อนจะไปถึงที่นั่นกันเถอะ!",
  ui_story_5020_50201501_85_dialog_content = "ตกลง. แล้ว...",
  ui_story_5020_50201501_86_dialog_content = "Amemori และ Yao จะเป็นผู้นำ Wisp เพื่อป้องกันทางผ่านระหว่าง Sakai และท่าเรือ",
  ui_story_5020_50201501_87_dialog_content = "รองและ PlayerNameโปรดอยู่ที่นี่เพื่อดูแลใครก็ตามที่ผ่านเข้ามาได้",
  ui_story_5020_50201501_88_dialog_content = "ฉันจะสู้กับพวกซามูไรที่ท่าเรือ",
  ui_story_5020_50201501_89_dialog_content = "ตามลำพัง? คุณแน่ใจไหม?",
  ui_story_5020_50201501_90_dialog_content = "คุณคิดว่านี่เป็นเวลาที่ดีที่จะถามทักษะของฉัน PlayerName?",
  ui_story_5020_50201501_91_dialog_content = "(รินเนะเปลี่ยนไปแล้วจริง ๆ...)",
  ui_story_5020_50201501_92_dialog_content = "ไปกันเลย!",
  ui_story_5020_50201501_93_dialog_content = "ไป!",
  ui_story_5020_50201501_94_dialog_content = "<anim type=Shake>กรรรร...</anim>",
  ui_story_5020_50201501_95_dialog_content = "พวกเขากำลังใกล้เข้ามาแล้ว",
  ui_story_5020_50201501_96_dialog_content = "ฮึ่ม! กำปั้นของฉันรู้สึกคันที่จะต่อสู้!",
  ui_story_5020_50201501_97_dialog_content = "ฉันขอตัวไปที่ท่าเรือก่อนนะ",
  ui_story_5020_50201501_98_dialog_content = "ปลอดภัยทุกคน เราจะผ่านสงครามนี้ไปด้วยกัน!",
  ui_story_5020_50201601_1_dialog_content = "<color=#e8d9bb>ทางเข้าท่าเรือเมืองโคฟุโจ</color>",
  ui_story_5020_50201601_2_dialog_content = "<color=#e8d9bb>ซึบ... ซึบ...</color>",
  ui_story_5020_50201601_3_dialog_content = "แฮ่ก... แฮ่ก...",
  ui_story_5020_50201601_4_dialog_content = "อึก... แค่ก!",
  ui_story_5020_50201601_5_dialog_content = "ท่านอาเมะโมริ!",
  ui_story_5020_50201601_6_dialog_content = "เธอบาดเจ็บ! ปกปิดการล่าถอยของเธอ!",
  ui_story_5020_50201601_7_dialog_content = "ไม่จำเป็น. เดินทางต่อไปยัง Sakai...",
  ui_story_5020_50201601_8_dialog_content = "อยู่เฉย ๆ รอตั้งรับอย่างเดียวเป็นกลยุทธ์ที่ไม่เข้าท่า",
  ui_story_5020_50201601_9_dialog_content = "เก็บแรงไว้ละกัน ไม่แสดงความเมตตาต่อศัตรู",
  ui_story_5020_50201601_10_dialog_content = "ถ้าเจอใครที่เกินจะรับมือ ปล่อยให้มันผ่านไป...",
  ui_story_5020_50201601_11_dialog_content = "Slice of Heaven ของเราจะจัดการพวกมันให้หมด!",
  ui_story_5020_50201601_12_dialog_content = "แต่เลดี้อาเมโมริ เธอเป็น...",
  ui_story_5020_50201601_13_dialog_content = "ฉันเคลียร์ตัวเองแล้วเหรอ?!",
  ui_story_5020_50201601_14_dialog_content = "รับทราบ!",
  ui_story_5020_50201601_15_dialog_content = "<color=#e8d9bb>ตึก ตึก ตึก...</color>",
  ui_story_5020_50201601_16_dialog_content = "แฮ่ก... แฮ่ก...",
  ui_story_5020_50201601_17_dialog_content = "ระวัง! อาเมะโมริ—",
  ui_story_5020_50201601_18_dialog_content = "<anim type=Shake>กรรรร!</anim>",
  ui_story_5020_50201601_19_dialog_content = "Ninjutsu - อย่างไม่หยุดยั้ง... เอ่อ...",
  ui_story_5020_50201601_20_dialog_content = "อาเมะโมริ!",
  ui_story_5020_50201601_21_dialog_content = "ฉันควรจะ... ระวังให้มากกว่านี้",
  ui_story_5020_50201601_22_dialog_content = "เหยา... มายืนหลังชนหลังกับฉันทางนี้",
  ui_story_5020_50201601_23_dialog_content = "โอเค! แต่ทำไม...",
  ui_story_5020_50201601_24_dialog_content = "อ๋า... เข้าใจแล้ว...",
  ui_story_5020_50201601_25_dialog_content = "Lins สอนฉันว่านักรบที่แท้จริงมักจะเผชิญหน้ากับศัตรู",
  ui_story_5020_50201601_26_dialog_content = "นินจาใช้กลยุทธ์เดียวกันหรือไม่?",
  ui_story_5020_50201601_27_dialog_content = "การหันหลังให้ศัตรูถือเป็นเรื่องใหญ่",
  ui_story_5020_50201601_28_dialog_content = "นินจาไม่กลัวการลอบโจมตีจากทุกทิศทาง",
  ui_story_5020_50201601_29_dialog_content = "อย่างไรก็ตาม ตอนนี้ฉันอ่อนแอกว่าปกติ",
  ui_story_5020_50201601_30_dialog_content = "ฉันเชื่อใจให้เธอคุ้มกันหลังได้ใช่ไหม?",
  ui_story_5020_50201601_31_dialog_content = "ฮะ! ถึงกับต้องถามเลยเหรอ?",
  ui_story_5020_50201601_32_dialog_content = "แม้ว่าเจ้าจะไม่ได้รับบาดเจ็บ... แม้ว่าเราจะไม่ถูกผูกมัดโดย Rebellion และ Ryojin...",
  ui_story_5020_50201601_33_dialog_content = "แต่เธอก็คือพี่น้องร่วมสนามรบของฉัน...",
  ui_story_5020_50201601_34_dialog_content = "และฉันจะช่วยคุณทุกอย่างที่ฉันมี!",
  ui_story_5020_50201601_35_dialog_content = "หึหึหึ... ตัดบทดราม่าได้",
  ui_story_5020_50201601_36_dialog_content = "ศัตรูเพิ่มเติมกำลังจะมา...",
  ui_story_5020_50201601_37_dialog_content = "พร้อมหรือยัง <color=#FFB400>ศิษย์น้อง</color>?",
  ui_story_5020_50201601_38_dialog_content = "แน่นอน! ฉันมีแรงเหลือเฟือ!",
  ui_story_5020_50201601_39_dialog_content = "ย้ากกกก!",
  ui_story_5020_50201601_40_dialog_content = "ฮ่าาาาห์... ฮ่าห์...",
  ui_story_5020_50201601_41_dialog_content = "อาเมโมริ คุณต้องอยู่ในนั้น...",
  ui_story_5020_50201601_42_dialog_content = "ฮึ่ม... ตามธรรมชาติ...",
  ui_story_5020_50201601_43_dialog_content = "... เหยา เอา Slice of Heaven!",
  ui_story_5020_50201601_44_dialog_content = "ไม่ชอบมาพากลแฮะ...",
  ui_story_5020_50201601_45_dialog_content = "ได้เลย!",
  ui_story_5020_50201601_46_dialog_content = "มีอะไรผิดปกติ? เราควรทำอย่างไร?",
  ui_story_5020_50201601_47_dialog_content = "... มุ่งหน้าสู่ซาไกกันเถอะ เราต้องซื้อเวลาให้กับ Rinne และพลเรือนที่ท่าเรือ",
  ui_story_5020_50201601_48_dialog_content = "ดูสภาพแวดล้อมของคุณ",
  ui_story_5020_50201601_49_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50201601_50_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50201601_51_dialog_content = "(ทหารโชคุยูกำลังต่อสู้กับลูกสมุนผีอยู่ทาง 2 นาฬิกา...)",
  ui_story_5020_50201601_52_dialog_content = "(และมีรอยเท้ามนุษย์ตอน 10 โมง...)",
  ui_story_5020_50201601_53_dialog_content = "(นกหกตัวเพิ่งออกจากป่าตอน 7 โมงเช้า...)",
  ui_story_5020_50201601_54_dialog_content = "(แปลกไม่ได้ยินเสียงผิดปกติ เกิดอะไรขึ้น?)",
  ui_story_5020_50201601_55_dialog_content = "...",
  ui_story_5020_50201601_56_dialog_content = "โอ๊ะ! อาเมะโมริ ทางนี้ ๆ!",
  ui_story_5020_50201601_57_dialog_content = "เงาคนนั่นมัน...",
  ui_story_5020_50201601_58_dialog_content = "ชาวเมืองโคฟุโจที่ยังอยู่งั้นเหรอ?",
  ui_story_5020_50201601_59_dialog_content = "แต่จะยังมีคนเหลืออยู่ในเมืองได้อย่างไร?",
  ui_story_5020_50201601_60_dialog_content = "เหยา! ระวัง!",
  ui_story_5020_50201601_61_dialog_content = "อะไรนะ?",
  ui_story_5020_50201601_62_dialog_content = "<anim type=Shake>...กาอา...</anim>",
  ui_story_5020_50201601_63_dialog_content = "เขาว่าอะไรนะ?",
  ui_story_5020_50201601_64_dialog_content = "<anim type=Shake>กรรรร...</anim>",
  ui_story_5020_50201601_65_dialog_content = "<size=50><anim type=Shake>โฮกก!</anim></size>",
  ui_story_5020_50201601_66_dialog_content = "นั่นมัน... ฟูจิคุโมะ?!",
  ui_story_5020_50201601_67_dialog_content = "... ไม่นะ!",
  ui_story_5020_50201601_68_dialog_content = "(ฟูจิคุโมะหนีจากมาสเตอร์และไปที่ท่าเรือได้อย่างไรในชิ้นเดียว?)",
  ui_story_5020_50201601_69_dialog_content = "(อาจารย์อาจจะเป็น...)",
  ui_story_5020_50201601_70_dialog_content = "อะไรนะ... มันคือมอนสเตอร์ประเภทไหนกันนะ?",
  ui_story_5020_50201601_71_dialog_content = "<anim type=Shake>นอนลง...</anim>",
  ui_story_5020_50201601_72_dialog_content = "<anim type=Shake>วางลง...</anim>",
  ui_story_5020_50201601_73_dialog_content = "เหยา ยึด Slice of Heaven ให้แน่น...",
  ui_story_5020_50201601_74_dialog_content = "เราอาจไม่ชนะ...",
  ui_story_5020_50201601_75_dialog_content = "แต่เราจะปล่อยให้ Slice of Heaven อยู่ในมือของเขาไม่ได้!",
  ui_story_5020_50201601_76_dialog_content = "เจ้านายของฉันอยู่ที่ไหน!",
  ui_story_5020_50201601_77_dialog_content = "<anim type=Shake>ฆ่า...</anim>",
  ui_story_5020_50201601_78_dialog_content = "<anim type=Shake>ฆ่า...</anim>",
  ui_story_5020_50201601_79_dialog_content = "อะไรนะ?",
  ui_story_5020_50201601_80_dialog_content = "...",
  ui_story_5020_50201601_81_dialog_content = "ฉันจะฆ่าคุณ! Ninjutsu - ร่องรอย...",
  ui_story_5020_50201601_82_dialog_content = "อ๊ากกก... *แค่ก*",
  ui_story_5020_50201601_83_dialog_content = "(... ฉันจะทำอะไรได้อีก ฉันถึง... ขีดจำกัดของฉันแล้ว...)",
  ui_story_5020_50201601_84_dialog_content = "<color=#e8d9bb>ฟึบ...ผัวะ</color>",
  ui_story_5020_50201601_85_dialog_content = "น้ำวนเชี่ยวกราก!",
  ui_story_5020_50201601_86_dialog_content = "Barrier... ปรับใช้!",
  ui_story_5020_50201601_87_dialog_content = "ทุกคน!",
  ui_story_5020_50201601_88_dialog_content = "เธอสองคนสู้มาหนักพอแล้ว!",
  ui_story_5020_50201601_89_dialog_content = "เราทำความสะอาดพื้นที่ของเราเรียบร้อยแล้ว! ตอนนี้มาโฟกัสที่การป้องกันการจ่ายบอลกัน!",
  ui_story_5020_50201601_90_dialog_content = "ซ่อนตัวอยู่หลังสิ่งกีดขวาง ให้ฉัน...",
  ui_story_5020_50201601_91_dialog_content = "อ๊ะ...",
  ui_story_5020_50201601_92_dialog_content = "นี่มัน...",
  ui_story_5020_50201601_93_dialog_content = "<size=45><anim type=Shake>โฮกก!</anim></size>",
  ui_story_5020_50201601_94_dialog_content = "<anim type=Shake>รินเนะ...</anim>",
  ui_story_5020_50201601_95_dialog_content = "<anim type=Shake>คุณ...กล้า...</anim>",
  ui_story_5020_50201601_96_dialog_content = "<size=50><anim type=Shake>โฮกก!</anim></size>",
  ui_story_5020_50201601_97_dialog_content = "นั่นนายพลฟูจิคุโมะเหรอ? เกิดอะไรขึ้นกับเขา?",
  ui_story_5020_50201601_98_dialog_content = "*ไอ* นั่นมันไม่สำคัญแล้วตอนนี้!",
  ui_story_5020_50201601_99_dialog_content = "รีบ! ฆ่าเขาด้วย Slice of Heaven...",
  ui_story_5020_50201601_100_dialog_content = "รินเนะ! รับ!",
  ui_story_5020_50201601_101_dialog_content = "มา!",
  ui_story_5020_50201601_102_dialog_content = "(นี่คือดาบศักดิ์สิทธิ์ที่มิโกะได้รับสืบทอดจากรุ่นสู่รุ่น...)",
  ui_story_5020_50201601_103_dialog_content = "(นักบวชหญิงจะใช้มันเพื่อฆ่าผี แต่นายพลได้กันมันไว้จากพวกเขา...)",
  ui_story_5020_50201601_104_dialog_content = "<color=#e8d9bb>ตุ้บ...ตุ้บ...ตุ้บ...</color>",
  ui_story_5020_50201601_105_dialog_content = "(อา... ท่านโชกุน... ท่านคุโบ... บางทีฉันควรเรียกท่านว่าท่านพ่อเป็นครั้งสุดท้าย...)",
  ui_story_5020_50201601_106_dialog_content = "(มือของฉันไม่สามารถหยุดสั่นได้เมื่อฉันถือ Slice of Heaven...)",
  ui_story_5020_50201601_107_dialog_content = "(ความกลัว ความกังวลใจ และความคาดหวังรวมกันเป็นหนึ่งเดียวในตัวฉัน...)",
  ui_story_5020_50201601_108_dialog_content = "(นี่ไม่ใช่สิ่งที่คุณเคยสอนฉัน...)",
  ui_story_5020_50201601_109_dialog_content = "<size=50><anim type=Shake>โฮกก!</anim></size>",
  ui_story_5020_50201601_110_dialog_content = "ท่านพ่อ...",
  ui_story_5020_50201601_111_dialog_content = "ได้โปรด... รับนี่ไป!",
  ui_story_5020_50201602_1_dialog_content = "<anim type=Shake>กรร...</anim>",
  ui_story_5020_50201602_2_dialog_content = "แฮ่ก... แฮ่ก...",
  ui_story_5020_50201602_3_dialog_content = "รินเนะ ตอนนี้แหละ!",
  ui_story_5020_50201602_4_dialog_content = "ย้ากก!",
  ui_story_5020_50201602_5_dialog_content = "<size=50><anim type=Shake>อ๊ากกกกกก!</anim></size>",
  ui_story_5020_50201602_6_dialog_content = "<anim type=Shake>ซ่า...</anim>",
  ui_story_5020_50201602_7_dialog_content = "<anim type=Shake>ฮือ...ฮือ...ฮือ...</anim>",
  ui_story_5020_50201602_8_dialog_content = "G-นายพล?",
  ui_story_5020_50201602_9_dialog_content = "สำเร็จแล้ว!",
  ui_story_5020_50201602_10_dialog_content = "ไล่ผีให้กลับเป็นมนุษย์...",
  ui_story_5020_50201602_11_dialog_content = "นี่เป็นพลังที่แท้จริงของ Slice of Heaven หรือไม่?",
  ui_story_5020_50201602_12_dialog_content = "รินเนะ... พวกนายเอา Slice of Heaven ไปจริงๆ...",
  ui_story_5020_50201602_13_dialog_content = "คุณทำดีแล้ว...",
  ui_story_5020_50201602_14_dialog_content = "มาหาฉัน...",
  ui_story_5020_50201602_15_dialog_content = "ท่านโชกุน ท่าน...",
  ui_story_5020_50201602_16_dialog_content = "คุณทำบาปมากเกินไปจนฉันไม่สามารถยกโทษให้...",
  ui_story_5020_50201602_17_dialog_content = "บางครั้งคุณอาจรู้สึกผิดหวังและหมดหนทาง แต่นั่นไม่ได้พิสูจน์ให้เห็นถึงการแสวงหาอำนาจอย่างเหี้ยมโหดของคุณ",
  ui_story_5020_50201602_18_dialog_content = "ไฟในโคฟุโจได้มอดลงแล้ว",
  ui_story_5020_50201602_19_dialog_content = "...และได้เวลาพักผ่อนแล้ว",
  ui_story_5020_50201602_20_dialog_content = "ผิดหวังและทำอะไรไม่ถูก? ฮ่าฮ่าฮ่า...",
  ui_story_5020_50201602_21_dialog_content = "คุณอ่านจดหมายหลังจากทั้งหมด",
  ui_story_5020_50201602_22_dialog_content = "นอกเหนือจากสิ่งที่คุณเห็น ยังมีสิ่งอื่น ๆ ที่คุณจะไม่มีวันเข้าใจ",
  ui_story_5020_50201602_23_dialog_content = "แต่คำเหล่านี้ไม่ใช่คำที่มาจากปากเด็ก",
  ui_story_5020_50201602_24_dialog_content = "รินเนะ คุณโตแล้ว",
  ui_story_5020_50201602_25_dialog_content = "จะไม่เรียกข้าว่าท่านคุโบเป็นครั้งสุดท้ายสักหน่อยหรือ?",
  ui_story_5020_50201602_26_dialog_content = "...",
  ui_story_5020_50201602_27_dialog_content = "ฮึ่ม! คุณไม่สมควรได้รับตำแหน่งนั้น!",
  ui_story_5020_50201602_28_dialog_content = "ฟูจิคุโมะ ยุคสมัยของแกจบลงแล้ว",
  ui_story_5020_50201602_29_dialog_content = "มองไปรอบ ๆ สิ",
  ui_story_5020_50201602_30_dialog_content = "บริการคุณถูกต้อง! นั่นคือสิ่งที่ฉันเรียกว่ากรรม",
  ui_story_5020_50201602_31_dialog_content = "คุกเข่าลง... ใช่ คุกเข่าลง... ฮ่าฮ่าฮ่า! ใครจะไปรู้ว่านายพลฟูจิคุโมะผู้สง่างามจะได้เห็นวันแบบนี้!",
  ui_story_5020_50201602_32_dialog_content = "เราจะเสียเวลาคุยกับเขาทำไม พี่น้อง จัดการเขาซะ! ข้อเสนอพิเศษสำหรับเทศกาล Kasuga!",
  ui_story_5020_50201602_33_dialog_content = "ถูกตัอง! ฆ่าเขา!",
  ui_story_5020_50201602_34_dialog_content = "ฮ่าฮ่า... ฮ่าฮ่าฮ่าฮ่า...",
  ui_story_5020_50201602_35_dialog_content = "บังอาจ!",
  ui_story_5020_50201602_36_dialog_content = "เลิกโง่สักที! การทำร้ายท่านคุโบะกำลังสร้างศัตรูให้กับเกาะหลักทั้งหมด!",
  ui_story_5020_50201602_37_dialog_content = "ใครจะสนใจเกาะหลัก?",
  ui_story_5020_50201602_38_dialog_content = "หันกลับมามองหาตัวเอง! ซามูไรของคุณยังมีลมหายใจอยู่กี่คน!? ฟูจิคุโมะ คุณสมควรได้รับสิ่งนี้!",
  ui_story_5020_50201602_39_dialog_content = "พี่น้องทั้งหลาย บุก!",
  ui_story_5020_50201602_40_dialog_content = "<color=#e8d9bb>แคล้ง...</color>",
  ui_story_5020_50201602_41_dialog_content = "ถอยไป!",
  ui_story_5020_50201602_42_dialog_content = "ถอยไป... *แค่ก* ถอยไป...",
  ui_story_5020_50201602_43_dialog_content = "คุณคิดว่า Cloud Island จะกลายเป็นสถานที่ที่ดีกว่าโดยการสังหาร General Fujikumo หรือไม่!",
  ui_story_5020_50201602_44_dialog_content = "...",
  ui_story_5020_50201602_45_dialog_content = "แม้ว่าคุณจะฆ่าแม่ทัพคนปัจจุบัน...",
  ui_story_5020_50201602_46_dialog_content = "นายพลคนใหม่จากเกาะหลักจะเข้ามาแทนที่ภายในครึ่งเดือน",
  ui_story_5020_50201602_47_dialog_content = "คุณจะโกรธใครในตอนนั้น?",
  ui_story_5020_50201602_48_dialog_content = "สำหรับคุณผู้ก่อการกบฏ Kubou-sama คือคนนอกที่คุณเหวี่ยงใส่",
  ui_story_5020_50201602_49_dialog_content = "แต่ในความเป็นจริง Kubou-sama ยังเป็นเพียงแค่หุ่นเชิดที่เต้นตามจังหวะของคนอื่น",
  ui_story_5020_50201602_50_dialog_content = "ยาม... เอาชายคนนี้ออกไป...",
  ui_story_5020_50201602_51_dialog_content = "(ฟูจิคุโมะ... ดูเหมือนจะพูดลำบาก...)",
  ui_story_5020_50201602_52_dialog_content = "ได้โปรดให้ผมได้พูดต่อเถอะ!",
  ui_story_5020_50201602_53_dialog_content = "... ท่านคุโบะประนีประนอมได้ทำเพื่อเอาใจเกาะหลัก...",
  ui_story_5020_50201602_54_dialog_content = "ความพยายามที่เขาทำเพื่อรักษาเกาะเมฆาให้สงบสุข... ทำไมพวกคุณถึงเข้าใจมันทั้งหมด?!",
  ui_story_5020_50201602_55_dialog_content = "จะว่าโหดก็ได้...จะว่าบิดก็ได้...",
  ui_story_5020_50201602_56_dialog_content = "แต่คุณคิดว่าสิ่งที่เขาแสวงหามันผิดจริงๆหรือ?",
  ui_story_5020_50201602_57_dialog_content = "...",
  ui_story_5020_50201602_58_dialog_content = "ฉันไม่ชอบที่เขาพูด...",
  ui_story_5020_50201602_59_dialog_content = "แต่ฉันคิดว่าเขามีประเด็น...",
  ui_story_5020_50201602_60_dialog_content = "ฉันเคยคิดมาก แต่ทุกคนที่นี่ใจง่ายเกินไปที่จะเข้าใจการเมืองที่ซับซ้อนเช่นนี้...",
  ui_story_5020_50201602_61_dialog_content = "ฉันสามารถจัดการ Cloud Island ได้ดีกว่า Fujikumo นี้ร้อยเท่า!",
  ui_story_5020_50201602_62_dialog_content = "นี่คืออะไร? เขาร้องเพลงและพวกคุณก็เริ่มเต้นตาม?!",
  ui_story_5020_50201602_63_dialog_content = "ก่อนจะบุกไปกำจัดศัตรู แกต้องข้ามศพฉันไปก่อน ที่ฉันเกลียดที่สุดก็พวกกบฏทรยศอย่างแกนี่แหละ!",
  ui_story_5020_50201602_64_dialog_content = "<color=#e8d9bb>เจี๊ยบ... จิ๊บ...</color>",
  ui_story_5020_50201602_65_dialog_content = "เฮ้... Kubou-sama ไม่มีประโยชน์สำหรับความเห็นอกเห็นใจที่ล่าช้าของคุณ",
  ui_story_5020_50201602_66_dialog_content = "สำหรับเขา ความเห็นอกเห็นใจของคุณคือความอัปยศอดสู!",
  ui_story_5020_50201602_67_dialog_content = "หุบปาก...",
  ui_story_5020_50201602_68_dialog_content = "ใช่! ทุกคนหุบปากไปซะ!",
  ui_story_5020_50201602_69_dialog_content = "มีเพียงไม่กี่คนที่เข้าใจ Kubou-sama...",
