  ui_story_5020_50201701_47_dialog_content = "...",
  ui_story_5020_50201701_48_dialog_content = "ท่านแม่ทัพ!",
  ui_story_5020_50201701_49_dialog_content = "คุณยังมีชีวิตอยู่!",
