  ui_story_5020_50201701_64_dialog_content = "หากคุณต้องการความช่วยเหลือในอนาคต เพียงติดต่อ Lin Guild ใน Umbraton, Astra!",
  ui_story_5020_50201701_65_dialog_content = "ฉันจะช่วยคุณไม่ว่าจะต้องเดินทางไกลแค่ไหน!",
