  ui_story_5020_50201701_67_dialog_content = "แต่ฉันจะต้องเดินทางที่เหลือของการเดินทางครั้งนี้ด้วยตัวฉันเอง",
  ui_story_5020_50201701_68_dialog_content = "ฉันจำเป็นต้องยุติการปกครองเกาะหลักเหนือเกาะเมฆา นั่นเป็นวิธีเดียวที่จะชำระคะแนนเก่าทั้งหมดเหล่านี้",
  ui_story_5020_50201701_69_dialog_content = "คุณกำลังจะไปเกาะหลัก?",
  ui_story_5020_50201701_70_dialog_content = "ท่านอาจารย์ ได้โปรด...",
  ui_story_5020_50201701_71_dialog_content = "ดูแลตัวเอง และนำเกาะเมฆาไปสู่อนาคตที่สดใสทีนะคะ",
