  ui_story_5020_50201701_98_dialog_content = "<size=30>สึกิ...</size>",
  ui_story_5020_50201701_99_dialog_content = "สึกิ...",
  ui_story_5020_50201701_100_dialog_content = "<color=#e8d9bb>บนถนนในเมืองเขตปราสาทโคฟุโจ</color>",
