  ui_story_5020_50201701_117_dialog_content = "ลูกค้าใหม่คงไม่กลับมาฟังเรื่องเดิม ๆ แน่!",
  ui_story_5020_50201701_118_dialog_content = "PlayerName, คุณจะเข้ากันได้ดีกับอาหารจานนี้แบบไหน?",
  ui_story_5020_50201701_119_dialog_content = "หา? ถามฉันเนี่ยนะ?",
  ui_story_5020_50201701_120_dialog_content = "ในความเห็นอันต่ำต้อยของฉัน...",
